WITH payload AS (SELECT $archive_payload$[{"id":"31add1b6-a612-5566-8eec-56096c098b20","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء العقار املؤجر لنهاية مدته -البينة على من ادعى - جتديد العقد -األصل عدم متديد عقد اإليجار -احلكم بإخاء العقار املؤجر .","document_number":"3441359","case_number":"33650298","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"إجارة -إخاء العقار املؤجر لنهاية مدته -البينة على من ادعى - جتديد العقد -األصل عدم متديد عقد اإليجار -احلكم بإخاء العقار املؤجر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/19 :‬هـ  ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3441359 :‬‬\n                          ‫َر ْق ُم الدعوى‪33650298 : :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34176756‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫إجــارة ‪ -‬إخــاء العقــار املؤجــر لنهايــة مدتــه ‪ -‬البينــة علــى مــن ادعــى ‪-‬‬\n      ‫جتديــد العقــد ‪ -‬األصــل عــدم متديــد عقــد اإليجــار ‪ -‬احلكــم بإخــاء‬\n                                                                      ‫العقــار املؤجــر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه صلــى اهلل عليــة وســلم « لــو يعطــى النــاس بدعواهــم الدعــى‬\n      ‫أنــاس دمــاء رجــال وأموالهــم ولكــن البينــة علــى املدعــي واليمــن علــى‬\n                                                                   ‫املدعــى عليــه»‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــة وســلم يف احلديــث املــروي يف صحيــح مســلم‬\n                 ‫يف قصــة الكنــدى « ألــك بينــة‪ .‬قــال ال‪ .‬قــال فلــك ميينــه»‬\n\n\n\n\n      ‫ادعــى املدعــى بــأن املدعــى عليــه أصالــة اســتأجر مــن موكلــه العقــار‬\n      ‫املوصــوف يف نــص القضيــة ملــدة ســنة بأجــرة ســنوية قدرهــا مائــة الــف‬\n      ‫ريــال وقــد قــام املؤجــر بإخبــار املســتأجر بعــدم الرغبــة يف التجديــد‬\n      ‫مبوجــب خطــاب اخطــار رفــض املســتأجر اســتالمه ولــذا فــإن املدعــى‬\n      ‫يطالــب الــزام املدعــى عليــه باإلخــاء ‪ -‬اجــاب املدعــى عليــه باملصادقــة‬\n      ‫ودفــع ان املؤجــر قــد مــدد لــه خمــس ســنوات يف العقــد وانكــر املدعــى‬\n      ‫ذلــك وليــس لديــه بينــة ‪ -‬طلــب املدعــى عليــة ميــن املدعــى اصالــة وحلــف‬\n‫‪267‬‬\n\f‫املدعــى اصالــة علــى نفــى التمديــد ‪ -‬بنــاء علــى االســباب املرصــودة يف‬\n‫نــص القضيــة ولقولــه صلــى  اهلل عليــه وســلم (( البينــه علــى املدعــي‬\n‫واليمــن علــى املدعــى عليــه )) صــدر احلكــم علــى املدعــى عليــه بإخــاء‬\n‫العقــار واذا لــم يخــل العقــار فيفتــح عنــوة بواســطة جلنــة مشــكلة حســب‬\n‫املتبــع ‪ -‬قــرر املدعــى القناعــة وقــرر املدعــى عليــه عــدم القناعــة ‪ .‬صــدر‬\n‫قــرار محكمــة االســتئناف مبكــة املكرمــة باملوافقــة علــى احلكــم‬\n                                                                  ‫باألكثريــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة مبكــة‬\n‫املكرمــة   وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس برقــم‬\n‫‪ 33650298‬وتاريــخ ‪ 1433/11 /13‬هــ  املقيــدة بهــذه احملكمــة برقــم‬\n‫‪ 332002893‬وتاريــخ ‪ 1433/  11  / 13‬ه ـ ففــي يــوم الثالثــاء  املوافــق‬\n‫‪1434/01/20‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة والنصــف‬\n‫صباح ـ ًا وفيهــا حضــر ســعودي بالســجل املدنــي رقــم حــال كونــه‬\n‫وكيــا مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة‬\n‫املكرمــة رقــم ‪ 29455‬وتاريــخ ‪1432/10/20‬ه ـ اجللــد ‪ 4991‬عــن‬\n‫ســعودي بالســجل املدنــي رقــم واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫واإلقــرار واإلنــكار والصلــح ‪ ...‬الــخ  وادعــى علــى احلاضــر معــه يف‬\n‫ا‬\n‫مجلــس احلكــم‪ ...‬ســعودي بالســجل املدنــي رقــم‪ ...‬حــال كونــه وكيـ ً‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بغــرب مكــة رقــم‬\n‫‪ 33326001‬وتاريــخ ‪1433/10/22‬ه ـ عــن ســعودي بالســجل املدنــي رقم‬\n\n                                                                                     ‫‪268‬‬\n\f      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واالقــرار واالنــكار وقبــول‬\n      ‫ا يف تقريــر دعــواه ضــده ‪ :‬إن موكلــي قد‬     ‫األحــكام ونفيهــا ‪...‬الــخ ‪  .‬قائـ ً‬\n      ‫أجــر املدعــى عليــه العقــار اململــوك لــه والكائــن باملســفلة ملــدة ســنة تبــدأ‬\n      ‫مــن ‪1433/01/01‬ه ـ وتنتهــي يف ‪1433/12/30‬ه ـ بأجرة ســنوية قدرها‬\n      ‫مائــة ألــف ريــال تدفــع علــى دفعتــن األولــى يف ‪1433/01/01‬ه ـ والدفعة‬\n      ‫الثانيــة يف ‪1433/09/20‬ه ـ وحيــث إن موكلــي قــد أخبــر املدعــى عليــه‬\n      ‫بعــدم رغبتــه يف جتديــد العقــد لفتــرة أخــرى يف ‪1433/11/07‬هــ  وذلــك‬\n      ‫مبوجــب خطــاب إخطــار بذلــك ورفــض اســتالم ذلــك لــذا ؛ أطلــب‬\n      ‫الــزام املدعــى عليــه بإخــاء العقــار إلنتهــاء مــدة ايجــاره هــذه دعــواي‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب بقولــه ‪ :‬مــا ذكــره‬\n      ‫املدعــي وكالــة مــن ناحيــة اســتئجار موكلــي ومدتــه وبدايتــه ونهايــة‬\n      ‫ـداء إال أن املدعــي أصالــة قــد وعــد موكلــي‬   ‫وقــدر األجــرة فصحيــح ابتـ ً‬\n      ‫بتجديــد العقــد خلمــس ســنوات إذا عمــل إصالحــات يف العقــار ليصبــح‬\n      ‫مطعم ـ ًا فوافــق موكلــي علــى ذلــك وقــام بهــذه االصالحــات ومــن ثــم‬\n      ‫فليــس لــدى موكلــي اســتعداد بإخــاء العقــار هكــذا أجــاب وبعــرض‬\n      ‫ذلــك علــى املدعــي وكالــة اجــاب بــأن ماذكــره املدعــى عليــه وكالــة‬\n      ‫غيــر صحيــح والصحيــح مــا ذكرتــه هكــذا اجــاب ثــم أبــرز املدعــي‬\n      ‫وكالــة صــورة عقــد اإليجــار الصــادر مــن مؤسســة إشــراقة العاصمــة‬\n      ‫غيــر مرقــوم واملــؤرخ يف ‪1433/01/01‬ه ـ واملتضمــن تأجيــر املدعــي‬\n      ‫للمدعــى عليــه العمــارة والــدكان الواقعــة يف ‪...‬حــارة ‪ ...‬مــدة اإليجــار‬\n      ‫تبــدأ مــن ‪1433/01/01‬ه ـ وتنتهــي يف ‪1433/12/30‬ه ـ وبأجــرة ســنوية‬\n      ‫مقدارهــا مائــة ألــف ريــال وبعــرض صــورة العقــد علــى املدعــى عليــه‬\n      ‫قــال ‪ :‬إن االتفــاق الــذي ذكرتــه حصــل مشــافهة بــن موكلــي واملدعــي‬\n\n\n‫‪269‬‬\n\f‫أصالــة الحقــا ‪ ،‬وحيــث أنكــر املدعــي وكالــة ذلــك فقــد ســألت‬\n‫املدعــى عليــه وكالــة البينــة فطلــب مهلــة للرجــوع ملوكلــه كمــا طلبــت‬\n‫مــن املدعــي وكالــة إحضــار صــك التملــك فوعــد بإحضــاره يف اجللســة‬\n‫القادمــة ولذلــك كلــه رفعــت اجللســة ثــم يف هــذا اليــوم  االثنــن املوافــق‬\n‫‪1434/02/18‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة و النصــف‬\n‫صباح ـ ًا وفيهــا حضــر املدعــي وكالــة املنــوه عنــه بعاليــه كمــا أحضــر‬\n‫املدعــي أصالــة ســعودي بالســجل املدنــي رقــم كمــا حضــر املدعــى‬\n‫عليــه أصالــة ســعودي بالســجل املدنــي رقــم وبســؤال املدعــي وكالــة‬\n‫عمــا وعــد بــه يف اجللســة املاضيــة مــن إحضــار صــك التملــك أبــرز الصــك‬\n‫الصــادر مــن كتابــة العــدل األولــى مبكــة املكرمــة برقــم ‪2/620/70‬‬\n‫يف ‪1430/06/28‬ه ـ وباالطــاع  عليــه وجــد أنــه يتضمــن متلــك املدعــي‬\n‫أصالــة لكامــل األنقــاض القائمــة باحلكــر علــى األرض الشــهيرة‬\n‫بوقــف ‪ ،...‬وبســؤال املدعــى عليــه عمــا وعــد بــه مــن بينــة أجــاب بــأن‬\n‫الشــاهد الــذي لــدي يشــهد بالتفــاوض مــع املدعــي وأطلــب ميــن املدعــي‬\n‫أصالــة علــى نفــي دعــواي بتمديــد العقــد خلمــس ســنوات وإذا حلــف‬\n‫تنتهــي دعــواي وبعــرض ذلــك علــى املدعــي أصالــة أفــاد بأنــه مســتعد‬\n‫باحللــف فجــرى وعظــه وتذكيــره مغبــة اليمــن الفاجــرة فكــرر مســتعد‬\n‫ا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب‬ ‫باحللــف وحلــف قائ ـ ً‬\n‫والشــهادة أنــي لــم أمــدد عقــد اإليجــار مــع املدعــى عليــه أو أي أحــد مــن‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى‬\n                                 ‫طرفــه ألكثــر مــن ســنة هكــذا حلــف فبنـ ً‬\n‫واإلجابــة وبعــد اإلطــاع علــى أوراق املعاملــة مبــا فيهــا مــن صــك امللكيــة‬\n‫وعقــد اإليجــار ‪ ،‬ومبــا أن املدعــي وكالــة قــد طلــب تكليــف املدعــى‬\n‫عليــه بإخــاء العقــار اململــوك ملوكلــه بالصــك الصــادر مــن كتابــة‬\n\n\n                                                                                     ‫‪270‬‬\n\f        ‫العــدل األولــى مبكــة برقــم ‪ 2/620/70‬يف ‪1430/06/28‬ه ـ النتهــاء‬\n        ‫مــدة إيجــاره يف ‪1433/12/30‬ه ـ ‪ ،‬وحيــث صــادق املدعــى عليــه علــى‬\n        ‫اإليجــار والعقــد ودفــع بــأن املدعــي قــد وعــده بتجديــد العقــد ملــدة خمــس‬\n        ‫ســنوات إذا عمــل إصالحــات ‪ ،‬وقــد قــام بهــذه اإلصالحــات ‪ ،‬ومبــا أن‬\n        ‫املدعــي وكالــة أنكــر ذلــك ‪ ،‬ومبــا أن املدعــى عليــه عجــز عــن إحضــار‬\n        ‫البينــة علــى جتديــد العقــد وطلــب ميــن املدعــي علــى نفــي دعــواه التمديــد‬\n        ‫‪ ،‬وحيــث إن األصــل عــدم التمديــد ‪ ،‬واملدعــى عليــه يدعــي بخــاف‬\n        ‫األصــل وهــو مــن يحمــل عــبء اإلثبــات ‪ ،‬ومبــا أن املدعــي بــذل اليمــن‬\n        ‫كمــا طلــب منــه ‪ ،‬ولقولــه صلــى اهلل عليــه وســلم يف احلديــث املــروي‬\n        ‫يف الصحيــح ‪(( :‬لــو يعطــى النــاس بدعواهــم الدعــى أنــاس دمــاء رجــال‬\n        ‫وأموالهــم ‪ ،‬ولكــن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه))‬\n        ‫‪ ،‬ولقولــه صلــى اهلل عليــه وســلم يف احلديــث املــروي يف صحيــح مســلم‬\n        ‫يف قصــة الكنــدي (( ألــك بينــه قــال ال قــال فلــك ميينــه ) ‪ ،‬ملــا ســبق‬\n      ‫فقــد حكمــت وألزمــت املدعــى عليــه بإخــاء العقــار موضــع الدعــوى  ‬\n        ‫وتســليمه للمدعــي ويف حالــة امتناعــه أو تغيبــه فيفتــح عنــوة بواســطة‬\n        ‫جلنــة مشــكلة مــن احملكمــة وشــعبة تنفيــذ األحــكام احلقوقيــة ويجلــى‬\n        ‫مــا فيهــا مــن بضائــع ويجــرد مــا فيهــا مــن منقــول ويــودع ببيــت املــال حلــن‬\n        ‫مطالبتــه بــه وبإعــان احلكــم عليهمــا قــرر املدعــي قناعتــه باحلكــم‬\n        ‫واملدعــى عليــه عدمهــا وطلــب اســتئنافه بالئحــة اعتراضيــة فأفهمتــه‬\n        ‫مبراجعــة احملكمــة يف يــوم االربعــاء املوافــق ‪1434/02/20‬ه ـ الســتالم‬\n        ‫نســخة مــن صــك احلكــم وأفهمتــه بــأن مــدة االعتــراض ثالثــون يومــا‬\n        ‫اعتبــار ًا مــن التاريــخ احملــدد لتســليمه صــورة الصــك وإذا لــم يتقــدم‬\n        ‫بالئحــة اعتراضيــة خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب‬\n\n\n‫‪271‬‬\n\f‫احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد حــرر يف‬\n                                                                  ‫‪1434/02/18‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬لــدي أنــا القاضــي باحملكمــة العامــة‬\n‫مبكــة املكرمــة القائــم بعمــل الشــيخ عليــه ففــي يــوم األحــد املوافــق‬\n‫‪1434/04/21‬ه ـ عــادت املعاملــة مــن محكمــة االســتئناف مبكــة‬\n‫املكرمة برقم ‪ 332002893‬وتاريخ ‪1434/04/10‬هـ واملقيدة بأســاس‬\n‫هــذه احملكمــة برقــم ‪ 33/2002893‬وتاريــخ ‪1434/04/16‬ه ـ املرفــق‬\n‫بهــا القــرار رقــم ‪ 34176756‬وتاريــخ ‪1434/04/02‬هــ  واملــدون علــى‬\n‫ظهــر الصــك املتضمــن املوافقــة علــى احلكــم باألكثريــة مــن الدائــرة‬\n‫احلقوقيــة الثالثــة ‪ .‬قاضــي اســتئناف توقيعــه وختمــه ‪ .‬قاضــي اســتئناف‬\n‫(لــي وجهــة نظــر) توقيعــه وختمــه ‪ .‬رئيــس الدائــرة توقيعــه وختمــه ‪ .‬لــذا‬\n‫جــرى حتريــر ذلــك وإحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/21‬ه ـ ‪.‬‬\n‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا احلكــم الص ــادر مــن‬\n‫فضي ــلة الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة املســجل‬\n‫بعــدد ‪ 3441359‬وتاريــخ ‪1434/2/19‬هـ ـ املتضمــن دعــوى يف مبلــغ‬\n‫مالــي احملكــوم فيــه مبــا دون باطنــه‪ .‬وبــدراس ــة احلكــم وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقـ ـ ـ ـ ــرر باألكثريــة املـ ــوافقـ ـ ـ ــة علــى احلكــم‬\n‫وباهلل تعالى التوفيق ‪  .‬وصلـى اهلل علـى نبيـنا محمـد وعلـى آلـه وصحبـه‬\n                                                                          ‫وس ــلم ‪،،‬‬\n\n\n\n                                                                                       ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":267,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83684a3253b2701faa955a55ad0f5502270ef948cd3a9a3be08dd817b360153e","normalized_text_hash":"7bf75f54148e20b418cd0c7b3247e1858e6d988043e978bbbb768beac191da88","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p267-3441359"},{"id":"71ace4c1-414a-5150-858f-8790184997d1","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء العن وعدم التجديد -توافر شرط عدم زيادة األجرة عند التجديد -انتهاء املدة للعقد -احلكم بإخاء العقار -1قول النبي صلى اهلل عليه وسلم «املسلمون على شروطهم» -2األصل يف الشروط الصحة ولزوم الوفاء بها .","document_number":"3445113","case_number":"3417914","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة واملعمد من فضيلته","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/24","year":"1434","subject":"إجارة -إخاء العن وعدم التجديد -توافر شرط عدم زيادة األجرة عند التجديد -انتهاء املدة للعقد -احلكم بإخاء العقار -1قول النبي صلى اهلل عليه وسلم «املسلمون على شروطهم» -2األصل يف الشروط الصحة ولزوم الوفاء بها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/24 :‬هـ ‪:‬‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3445113 :‬‬\n                           ‫َر ْق ُم الدعوى‪3417914 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34211938‬تاريخه‪1434/5/13 :‬هـ‬\n\n\n      ‫إجــارة ‪ -‬إخــاء العــن وعــدم التجديــد ‪ -‬توافــر شــرط عــدم زيــادة األجرة‬\n                 ‫عنــد التجديــد ‪ -‬انتهــاء املــدة للعقــد ‪ -‬احلكــم بإخــاء العقار‬\n\n\n\n\n                 ‫‪ -1‬قول النبي صلى اهلل عليه وسلم «املسلمون على شروطهم»‬\n                          ‫‪ -2‬األصل يف الشروط الصحة ولزوم الوفاء بها ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى بأنــه أجــر للمدعــى عليــه شــقة ملــدة ســنتني ونصــف وقــد‬\n      ‫انتهــت مــدة اإليجــار وقــد اخبــر املدعــى عليــه بزيــادة األجــرة ولكــن‬\n      ‫املدعــى عليــه رفــض الزيــادة وطلــب املدعــى إلــزام املدعــى عليــه بإخــاء‬\n      ‫الشــقة ‪ -‬أجــاب املدعــى عليــة بــان مــا ذكــره املدعــى صحيــح ولكــن‬\n      ‫يوجــد شــرط يف العقــد وهــو أنــه يف حالــة التجديــد فإنــه ال زيــادة يف‬\n      ‫األجــرة ‪ -‬أجــاب املدعــى باملصادقــة علــى الشــرط ولكنــه يرفــض‬\n      ‫التجديــد ويطلــب اإلخــاء ‪ -‬نظــرا ألن املدعــى يطالــب باإلخــاء وليــس‬\n      ‫جتديــد العقــد فقــد صــدر احلكــم بالــزام املدعــى عليــه بإخــاء الشــقة ‪-‬‬\n                                      ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫‪273‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام اهلل علــى مــن ال نبــي بعــده وبعــد‬\n‫فلــدي أنــا‪ ...‬املــازم القضائــي لــدي الشــيخ‪  ..‬القاضــي يف احملكمــة‬\n‫العامــة باملدينــة املنــورة  واملعمــد مــن فضيلتــه وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة باملدينــة املنورة برقــم ‪3417914‬‬\n‫وتاريــخ ‪ 1434/01/11‬هــ  املقيــدة باحملكمــة برقــم ‪ 3484010‬وتاريــخ‬\n‫‪ 1434/01/11‬ه ـ وفيهــا حضــر املدعــي ‪  ..‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم  قائــا‪ :‬إننــي اســتأجرت عمــارة كاملــة‬\n‫تقــع يف ‪ ...‬مــن ‪...‬مبوجــب عقــد اإليجــار املرفــق باملعاملــة وقــد اســتثمرت‬\n‫هــذه العمــارة فقمــت بتأجيرهــا ومــن ضمــن املســتأجرين هــذا احلاضــر‬\n‫معــي أجرتــه الشــقة رقــم (‪ )3‬بأجــرة قدرهــا تســعة وخمســون ألــف ريــال‬\n‫ملــدة ســنتني ونصــف ‪ ،‬تبــدأ مــن تاريــخ ‪1431/7/8‬هــ  وتنتهــي بتاريــخ‬\n‫‪1434/1/8‬هــ  مبوجــب عقــد اإليجــار املرفــق باملعاملــة وأبــرز العقــد‬\n‫وقــد انتهــت مــدة اإلجــارة واإليجــارات قــد ارتفعــت وأخبرنــا جميــع‬\n‫املســتأجرين بالزيــادة ولكــن املدعــى عليــه رفــض الزيــادة فــاآلن أطلــب‬\n‫منــه إخــاء الشــقة حــاال هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه أجــاب بقولــه مــا ذكــره املدعــي صحيــح ولكننــي يف عقــد اإلجــار‬\n‫أضفــت شــرطا وهــو يف حالــة جتديــد العقــد بــن الطرفــن عــدم زيــادة‬\n‫اإليجــار هــذه إجابتــي وبعــرض ذلــك علــى املدعــي أجــاب بقولــه ما ذكره‬\n‫صحيــح ولكــن ال أريــد جتديــد العقــد معــه واطلــب منــه اإلخــاء وليــس‬\n‫جتديــد العقــد هــذه إجابتــي وبعرضــه علــى املدعــى عليــه أجــاب توجــد‬\n\n                                                                                            ‫‪274‬‬\n\f        ‫جتديــدات قمــت بهــا يف الشــقة وكذلــك فــك وتركيــب األثــاث وغيرهــا‬\n        ‫وأبــرز ورقــة طلــب إرفاقهــا جــرى االطــاع عليهــا ولــم أجــد فيهــا مــا يؤثــر‬\n        ‫علــى الدعــوى فأرفقتهــا باملعاملــة وبعــرض ذلــك علــى املدعــي أجــاب‬\n        ‫بقولــه ال عالقــة للمؤجــر بالتحســينات ونقــل األثــاث مالــم ينــص علــى‬\n        ‫ذلــك بالعقــد وجــرى ســؤال املدعــي هــل يوجــد اتفــاق حصــل خــارج العقــد‬\n        ‫بشــأن التمديــد يف عقــد اإلجــارة فأجــاب بقولــه لــم يحصــل أي اتفــاق‬\n        ‫غيــر العقــد هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n        ‫ولطلــب املدعــي إخــاء العــن املؤجــرة ولدفــع املدعــى عليــه بأنــه يوجــد‬\n        ‫يف عقــد اإلجــارة شــرط عــدم الزيــادة يف األجــرة حــال جتديــد العقــد‬\n        ‫وجلــواب املدعــي بأنــه يطلــب اإلخــاء وليــس جتديــد العقــد وألن األصــل‬\n        ‫يف الشــروط الصحــة ولــزوم الوفــاء بهــا مــا تخالــف الشــريعة وحلديــث‬\n        ‫النبــي صلــى اهلل عليــه وســلم (( املســلمون علــى شــروطهم )) رواه أبــو‬\n        ‫داود وأحمــد والــدار قطنــي لذلــك كلــه فقــد حكمــت علــى املدعــى‬\n        ‫عليــه بإخــاء الشــقة املوصوفــة بعاليــه وبعــرض احلكــم علــى املدعــي‬\n        ‫قــرر القناعــة وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم القناعــة‬\n        ‫وأفهمــت املدعــى عليــه باحلضــور غــدا الســتالم نســخة من احلكــم لتقدمي‬\n        ‫اعتراضــه وأن لــه مــدة ثالثــن يومــا إن لــم يتقــدم بالئحــة اعتراضيــة‬\n        ‫ســقط حقــه يف االســتئناف واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪  .‬حــرر يف  ‬\n                                                                        ‫‪1434/02/24‬ه ـ‬\n        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة باملدينــة‬\n        ‫املنــورة فقــد وردت املعاملــة مــن محكمــة االســتئناف بقرارهــا رقــم‬\n      ‫‪ 34211938‬يف ‪1434/5/13‬هــ  الصــادر مــن الدائــرة احلقوقيــة األولــى  ‬\n\n\n‫‪275‬‬\n\f‫املتضمــن أنــه بدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم  ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/04‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم‬\n‫الصــادر مــن فضيلــة الشــيخ املــازم القضائــي لــدى الشــيخ القاضــي‬\n‫باحملكمــة العامــة باملدينــة املنــورة واملســجل بعــدد ‪ 3445113‬وتاريــخ‬\n‫‪1434/2/24‬هـ ـ واملتضمــن دعــوى‪ .../‬ضــد‪ .../‬واحملكــوم فيــه مبــا دون‬\n                                                                          ‫باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                          ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪276‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":273,"source_page_end":276,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e19330a37dd927a35f2900fd5ebf94fac8b2759624f6506ae6ff7e9cda756a0","normalized_text_hash":"b4c5cfd51189a6a920ead498ae688e0aa6f436a1d491a3f36e85859f14809844","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p273-3445113"},{"id":"e0c1cbfd-435e-5060-816f-e9aea4f76bfd","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار -ادعاء صورية عقد اإليجار -عدم اعتبار دعوى صورية العقد -األصل التخلية بن املالك وملكه وعدم احليلولة بينهما -احلكم بإخاء العن وتسليم العقار بعد تصفية فاتورتي املاء والكهرباء .","document_number":"3449949","case_number":"32194894","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/27","year":"1434","subject":"إجارة -إخاء عقار -ادعاء صورية عقد اإليجار -عدم اعتبار دعوى صورية العقد -األصل التخلية بن املالك وملكه وعدم احليلولة بينهما -احلكم بإخاء العن وتسليم العقار بعد تصفية فاتورتي املاء والكهرباء .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/27 :‬هـ  ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3449949 :‬‬\n                          ‫َر ْق ُم الدعوى‪32194894 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34284867‬تاريخه‪1434/8/1 :‬هـ‬\n\n\n      ‫إجــارة ‪ -‬إخــاء عقــار ‪ -‬ادعــاء صوريــة عقــد اإليجــار ‪ -‬عــدم اعتبار دعوى‬\n      ‫صوريــة العقــد ‪ -‬األصــل التخليــة بــن املالــك وملكــه وعــدم احليلولــة‬\n      ‫بينهمــا ‪ -‬احلكــم بإخــاء العــن وتســليم العقــار بعــد تصفيــة فاتورتــي‬\n                                                                 ‫املــاء والكهربــاء ‪.‬‬\n\n\n\n\n                                    ‫قوله تعالي «يا أيها الذين امنوا اوفوا بالعقود»‬\n\n\n\n\n      ‫ادعــى املدعيــان وكالــة ضــد املدعــى عليــه وكالــة وتتضمــن دعواهمــا‬\n      ‫ان موكلتهمــا قــد اجــرت علــى املدعــى عليــه اصالــة فندقــا يف مكــة‬\n      ‫املكرمــة بأجــرة ســنوية ذكــر قدرهــا ملــدة عــام كامــل وال يتجــدد‬\n      ‫العقــد إال بعقــد جديــد وقــرر ان مــدة العقــد انتهــت ولــم يتــم جتديــد‬\n      ‫العقــد وقــد مت إخطــار املدعــى عليــه بإخــاء الفنــدق ورفــض ذلــك وطلــب‬\n      ‫املدعيــان وكالــة إخــاء العــن املؤجــرة وتســليمها كمــا اســتلمها ودفــع‬\n      ‫اتعــاب احملامــي والتعويــض عــن أي اضــرار  يف الفنــدق ‪  -‬أجــاب املدعــى‬\n      ‫عليــه وكالــة بــأن موكلــه قــد اســتأجر الفنــدق موطــن الدعــوى ولكــن‬\n      ‫مت ذلــك بالعقــد مــع شــخص اخــر غيــر املدعيــة وطلــب املدعــى عليــة‬\n\n‫‪277‬‬\n\f‫وكالــة صــرف النظــر عــن الدعــوى النعــدام صفــة املدعيــة يف العقــد ‪-‬‬\n‫أجــاب املدعيــان بالوكالــة بــان موكلتهمــا هــي مالكــة منفعــة الفنــدق‬\n‫ولهــا أحقيــة إبــرام عقــود التأجيــر مــع الغيــر كمــا أجابــا أن موكلتهمــا‬\n‫ســبق أن أجــرت الفنــدق علــى شــخص آخــر مثــل املدعــى عليــه ثــم أجرتــه‬\n‫علــى املدعــى عليــه ثــم جــددت العقــد معــه مــرة أخــري حســب رغبتــه‬\n‫مبوجــب عقــد وســند تســليم ‪ -‬طلــب ناظــر القضيــة مــن املدعــى وكالــة‬\n‫البينــة علــى دعــواه فابــرز عقــد إيجــار مبــرم مــع املدعيــة أصالــة وميثلهــا‬\n‫يف العقــد وكيلهــا الشــرعي وبــن  املدعــى عليــه ويتضمــن العقــد تأجيــر‬\n‫الفنــدق موطــن الدعــوى علــى املدعــى عليــه ومشــار يف العقــد إلــى بنــود‬\n‫مدونــة يف نــص القضيــة ومشــار إلــى أنــه وقــع الطرفــان علــى العقــد ‪-‬‬\n‫قــرر املدعــى وكالــة انــه ليــس لديــه بينــة ســوي مــا قــدم ‪ -‬جــرى عــرض‬\n‫العقــد علــى املدعــى عليــه وكالــة فأجــاب بــأن العقــد مــع املدعيــة عقــد‬\n‫صــوري ألجــل إكمــال اإلجــراءات اخلاصــة بلجنــة املســاكن واحلــج وقــرر‬\n‫أن الصحيــح أن هنــاك عقــد تشــغيل بــن موكلــه وبــن شــخص آخــر‬\n‫بخصــوص الفنــدق موطــن الدعــوى وقــد أبــرز املدعــى عليــه وكالــة‬\n‫هــذا العقــد ومت اطــاع ناظــر القضيــة عليــه ومت رصــده يف القضيــة ‪-‬‬\n‫وجــد ناظــر القضيــة مــن ضمــن طيــات املعاملــة عقــدا يتضمــن اســتئجار‬\n‫املدعيــة أصالــة للفنــدق موطــن الدعــوى مــن ناظــر الوقــف ومت عرضــه‬\n‫علــى املدعــى عليــه  وكالــة فقــال إنــه ال علــم لــه بهــذا العقــد‪ -‬قــرر‬\n‫ناظــر القضيــة أنــه بنــاء علــى الدعــوى واإلجابــة ولعــدم طعــن املدعــى‬\n‫عليــه وكالــة يف عقــد اســتئجار املدعيــة للفنــدق  ألن للعقــد آثــار وهــي‬\n‫النفــاذ وااللتــزام واللــزوم‪ ،‬وحيــث إن دفــع املدعــى عليــه وكالــة بصوريــة‬\n‫العقــد ال محــل لــه ملــا جــاء يف أســباب احلكــم ‪ -‬فقــد صــدر احلكــم‬\n\n\n                                                                                       ‫‪278‬‬\n\f      ‫علــى املدعــى عليــه بــأن يخلــى العــن محــل الدعــوى وتســليمها للمدعيــة‬\n      ‫كمــا اســتلمها بعــد تصفيــة فاتورتــي الكهربــاء واملــاء ‪ -‬قــرر املدعــى‬\n      ‫عليــه وكالــة عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة‬\n                                            ‫املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n        ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n        ‫العامــة مبكــة املكرمــة برقــم ‪ 32194894‬وتاريــخ ‪ 1432/05/26‬ه ـ‬\n        ‫املقيــدة باحملكمــة برقــم ‪ 32608612‬وتاريــخ ‪ 1432/05/26‬ه ـ املتعلقة‬\n        ‫بدعــوى ضــد ففــي هــذا اليــوم الثالثــاء ‪1432/11/20‬هـ أفتتحت اجللســة‬\n        ‫الســاعة ‪  01 : 00‬وفيهــا حضــر وكيــل املدعيــة املدعــو بالســجل املدنــي‬\n        ‫رقــم  بوكالتــه عــن املدعيــة مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n        ‫عــدل عرقــة رقــم ‪ 1/18‬يف ‪1427/11/8‬ه ـ املتضمــن املخاصمــة وســماع‬\n        ‫الدعــاوي وإقامــة البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه الــخ‬\n        ‫وحضــر وكيــل املدعيــة املدعــو بالســجل املدنــي  مبوجــب الوكالــة‬\n        ‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة رقــم ‪ 3076‬يف‬\n        ‫‪1430/1/27‬ه ـ املتضمــن املداعــاة واملخاصمــة وســماع الدعــاوي والــرد‬\n        ‫عليهــا وإقامــة البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه الــخ‬\n      ‫وحضــر حلضورهمــا وكيــل املدعــى عليــه املدعــو بالســجل املدنــي رقــم  ‬\n        ‫بوكالتــه عــن املدعــى عليــه مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n        ‫عــدل الثانيــة باجلمــوم رقــم ‪ 2219‬يف ‪1432/10/28‬ه ـ املتضمــن املرافعــة‬\n\n‫‪279‬‬\n\f‫واملدافعــة واملطالبــة بكافــة احلقــوق وإحضــار البينــة والشــهود واالقــرار‬\n‫واإلنــكار والصلــح وإســتالم والتســليم وانهــاء كافــة االجــراءات‬\n‫والتوقيــع الــخ ثــم ســألت املدعيــان وكالــة عــن دعواهمــا فأبــرز املدعــي‬\n‫وكالــة مــن يــده محــررا ذكــر بأنــه دعــواه ويتضمــن اآلتــي ‪ :‬صاحــب‬\n‫الفضيلــة أقــدم دعــواي هــذه ضــد املدعــى عليــه املدعــو وموضــوع‬\n‫الدعــوى بالتفصيــل مــا يلــي ‪ :‬إن املدعــى عليــه اســتأجر مــن موكلتــي‬\n‫الفنــدق الكائــن مبكــة املكرمــة شــارع ‪  ...‬املســمى بفنــدق ‪  ...‬وذلــك‬\n‫بقيمــة إيجاريــة ســنوية قدرهــا (‪ )1300000‬مليــون وثالثمائــة ألــف ريــال‬\n‫وذلــك ملــدة عــام كامــل يبــدأ مــن تاريــخ ‪1431/1/3‬ه ـ هجــري وينتهــي‬\n‫بتاريــخ ‪1431/12/30‬ه ـ هجــري و ال يتجــدد العقــد إال بعقــد جديــد‬\n‫آخــر و حيــث أن مــدة العقــد انتهــت ولــم يتــم جتديــد العقــد ملــدة أخــرى‬\n‫فــإن موكلتــي قامــت بإخطــار املدعــى عليــه بإخــاء الفنــدق املذكــور‬\n‫النتهــاء العالقــة اإليجاريــة مبوجــب العقــد إال أن املدعــى عليــه يرفــض‬\n‫تســليم الفنــدق املذكــور وحيــث إن عقــد اإليجــار  املبــرم بــن موكلــي‬\n‫وبــن املدعــى عليــه ينــص صراحــة علــى أن ملوكلتــي احلــق يف اســتالم‬\n‫املبنــى وحيازتــه بتاريــخ ‪1432/1/1‬ه ـ دون الرجــوع إلــى الطــرف الثانــي‬\n‫و دون موافقتــه وعلــى ذلــك فــإن املدعــى عليــه مياطــل يف تســليم موكلتــي‬\n‫الفنــدق املذكــور ومســتنداتي وبياناتــي مــا يلــي ‪ :‬عقــد اإليجــار  املبــرم‬\n‫بــن موكلتــي وبــن املدعــى عليــه وأطلــب مــا يلــي‪ :‬أوال إخــاء العــن‬\n‫وتســليمه كمــا اســتلمه منــا حســب اجلــرد ومبوجــب البنــد احلــادي‬\n‫عشــر يف العقــد حــال خــروج احلجــاج بعــد أداء فريضــة احلــج فــورا دون‬\n‫مماطلــة وعــدم تســليمه للغيــر والتعهــد بذلــك خطيــا أمــام فضيلتكــم‬\n‫وتســجيل ذلــك بالصــك إلبــرام احلجــة ثانيــا ‪ :‬دفــع أتعــاب احملامــي‬\n\n\n                                                                                   ‫‪280‬‬\n\f        ‫ســتون الــف ريــال وتعويضنــا عــن أي أضــرار إن وجــدت ال قــدر اهلل يف‬\n        ‫الفنــدق أ‪.‬هــ‪ .‬و بعــرض ذلــك علــى املدعــى عليــه وكالــة أبــرز مــن يــده‬\n        ‫محــررا قــرر بأنــه جوابــه عــن الدعــوي و باإلطــاع عليــه وجدتــه يتضمــن‬\n      ‫اآلتــي‪ :‬ملــا تقدمــت املدعيــة يف الئحــة دعواهــا باملطالبــة بإخــاء فنــدق ‪  ...‬‬\n        ‫واملطالبــة بأجــرة املثــل لعــام ‪1432‬ه ـ قامــت بتقــدمي مســتند عبــارة عــن‬\n        ‫عقــد ايجــار  زعمــت أنــه بينهــا وبــن موكلــي ‪ ،‬وحيــث أنــه قــد اســتلمنا‬\n        ‫الئحــة الدعــوى بالفاكــس دون ارفــاق املســتند وقــد طلبنــا مــن وكيــل‬\n        ‫املدعيــة واحلاضــر يف جلســة ‪1432/10/30‬ه ـ املدعــو مــرار ًا وتكــرار ًا‬\n        ‫عبــر الهاتــف بإرســال املســتند عبــر الفاكــس أو تســليمه إيانــا شــخصي ًا‬\n        ‫ا أن (املستشــار مؤمتــن) وبرفضــه تســليمي إيــاه‬   ‫إال أنــه رفــض ذلــك معلـ ً‬\n        ‫رغــم تنبيهكــم عليــه بضــرورة إعطائــي نســخة منــه وذلــك رغبتـ ًا منــه يف‬\n        ‫إطالــة أمــد النــزاع وإحلــاق الضــرر مبوكلــي بإثــارة اإلشــاعات املغرضــة‬\n        ‫بــأن العقــار عليــه منازعــات قضائيــة وتشــويه ســمعته يف الســوق لصــد‬\n        ‫النــاس عــن اســتئجاره (لكســر قيمتــه الســوقية) وبذلــك ســنورد الــرد‬\n        ‫علــى الئحــة الدعــوى مبــا يلــي‪ :‬أوالً‪ :‬نقــدم لفضيلتكــم صــورة مــن عقــد‬\n          ‫التشــغيل لعــام ‪1431‬ه ـ للعقــار املذكــور يف هــذه الدعــوى (فنــدق ‪) ...‬‬\n        ‫واملبــرم بــن الطــرف األول والطــرف الثانــي ملــدة عــام كامــل والــذي‬\n        ‫يبــدأ مــن تاريــخ ‪1431/01/01‬ه ـ وينتهــي بتاريــخ ‪1431/12/30‬ه ـ‬\n        ‫ويظهــر فيــه لفضيلتكــم أن املدعيــة ليــس لهــا أي صفــة يف العقــد املرفــق‬\n        ‫(مســتند رقــم (‪ .))01‬ثانيـاً‪ :‬نقــدم لفضيلتكــم صــورة مــن عقــد التنــازل‬\n        ‫عــن الفنــدق بــن الطــرف األول مؤسســة ‪ ...‬والطــرف الثانــي املبــرم‬\n        ‫بتاريــخ ‪1431/10/09‬ه ـ والــذي يبــدأ اســتثماره مــن ‪1432/01/01‬ه ـ‬\n        ‫وينتهــي بتاريــخ ‪1440/12/30‬ه ـ واملذكــور يف البنــد الرابــع مــن هــذا‬\n\n\n‫‪281‬‬\n\f‫العقــد ‪ :‬يحــق للطــرف الثانــي بيــع اســتثمار الفنــدق يف أي وقــت يشــاء)‬\n‫مرفــق (مســتند رقــم (‪ .))02‬ثالث ـاً‪ :‬نقــدم لفضيلتكــم صــورة مــن عقــد‬\n‫إيجــار الفنــدق (فنــدق ‪ ) ...‬لعــام ‪1432‬ه ـ واملبــرم بــن الطــرف األول‬\n‫(املالــك اجلديــد لعقــد اســتثمار فنــدق ‪ ) ...‬والطــرف الثانــي ملــدة عــام‬\n‫كامــل والــذي يبــدأ مــن ‪1432/01/01‬ه ـ وينتهــي بتاريــخ‬\n‫‪1432/12/30‬ه ـ ويظهــر فيــه لفضيلتكــم أن املدعيــة ليــس لهــا أي‬\n‫صفــة يف العقــد املرفــق (مســتند رقــم (‪ . ))03‬لــذا نطلــب مــن فضيلتكــم‬\n‫‪-1:‬صــرف النظــر عــن الدعــوى النعــدام صفــة املدعيــة يف الدعــوى‪.‬‬\n‫‪-2‬إلــزام املدعيــة بالتعهــد بعــدم رفــع أي دعــوى تخــص العقــار املذكــور‬\n‫وعــدم التعــرض لــه‪ -3 .‬إلــزام املدعيــة دفــع أتعــاب احملامــاة والبالــغ‬\n‫قدرهــا (‪80.000‬ريــال) ثمانــون ألــف ريــال فقــط وبعــرض ذلــك علــى‬\n‫املدعيــن وكالــة طلبــا نســخة مــن ذلــك لإلجابــة عليــه ويف يــوم الســبت‬\n‫‪1433/1/29‬ه ـ افتتحــت اجللســة وفيهــا حضــر املتداعــون بالوكالــة ثــم‬\n‫ســألت املدعيــان وكالــة عــن جوابهــم الــذي اســتمهلوا ألجلــه يف جلســة‬\n‫هــذا اليــوم فأجابــوا قائلــن صاحــب الفضيلــة إن زميلــي وكيــل املدعــي‬\n‫عليــه قــال أن موكلتــي تزعــم أن بينهــا وبــن املدعــي عليــه عقــد فأقــول‬\n‫وبحمــد اهلل إن موكلتــي ليســت بحاجــة إلــي أن تزعــم ألن موكلتــي‬\n‫لديهــا املســتندات والبراهــن التــي تخولهــا التأجيــر منــذ أربعــة ســنوات‬\n‫وهــي التــي متلــك املنفعــة ولهــا األحقيــة يف إبــرام عقــود التأجيــر حاليــا‬\n‫ومســتقبال ‪ ،‬صاحــب الفضيلــة قامــت موكلتــي بتشــغيل الفنــدق يف‬\n‫الســنة األولــى عــام ‪1428‬ه ـ ويف عــام ‪1429‬هـ قامــت موكلتي بتأجيرها‬\n‫للشــيخ مبوجــب عقــد وســند التســليم وتنــازل التصريــح مســتند رقــم(‪)1‬‬\n‫ثــم قامــت بتأجيرهــا للمدعــي عليــه مــن ‪1430/1/1‬ه ـ إلــى‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫‪1430/12/30‬ه ـ مبوجــب عقــد وســند التســليم حســب اجلــرد وشــيك‬\n      ‫باملبلــغ مســتند رقــم(‪ )2‬ومبوجــب البنــد الرابــع يف العقــد الــذي بينهمــا‬\n      ‫قامــت موكلتــي للمدعــي عليــه بتجديــد العقــد لــه حســب رغبتــه بتاريــخ‬\n      ‫‪1431/1/3‬ه ـ إلــى ‪1431/12/30‬ه ـ مســتند رقــم(‪  )3‬صاحــب الفضيلة‬\n      ‫إن موكلتــي متلــك املنفعــة وأحقيــة إبــرام عقــود التأجيــر مبوجــب العقــد‬\n      ‫الــذي لديهــا واملبــرم  بــن الطرفــن األول والطــرف الثانــي الــذي يبــدأ يف‬\n      ‫‪1428/1/1‬ه ـ وينتهــي بانتهــاء الفتــرة الباقيــة مــن االســتثمار يف‬\n      ‫‪1440/12/30‬هــ   واملصــدق مــن الغرفــة التجاريــة مســتند رقــم(‪.)4‬‬\n      ‫صاحــب الفضيلــة أقــول وبــكل أســف إن املدعــي عليــه هــو مــن يزعــم‬\n      ‫ومياطــل ويــراوغ ويتآمــر ويخــادع لكونــه مغتصبــا حقــوق الضعفــاء وال‬\n      ‫ميلــك املنفعــة وليــس لــه صفــة وهــو مــن يريــد إطالــة النــزاع وإثــارة‬\n      ‫اإلشــاعات بإبــرازه عقــود باطلــة ليــس لهــا صفــة البتــه وبنيــت هــذه العقود‬\n      ‫علــى تصــرف باطــل وخــداع وطــرق ملتويــة وغــرر وتواطــأ لتحريــض‬\n      ‫املدعــي عليــه لعــدم اخلــروج وتســليم املبنــى لكــون هــذه العقــود كانــت‬\n      ‫مدبــرة وموقعــة قبــل شــهرين مــن انتهــاء عقــد موكلتــي واســتالمها‬\n      ‫الفنــدق ‪ ،‬ولســماع موكلتــي هــذه األمــور التــي جــرت خلــف الســتار مــن‬\n      ‫غــرر وتواطــؤ اضطــرت املجــيء مــن الريــاض والوقــوف حليــازة الفنــدق‬\n      ‫مبوجــب البنــد الرابــع يف العقــد  بتاريــخ ‪1432/3/1‬ه ـ وهــي حاملــة‬\n      ‫جنينهــا يف شــهرها الثامــن لكــي حتمــي وتســترد حقوقهــا وحقــوق‬\n      ‫األيتــام واألرامــل مــن املغتصبــن اجلبابــرة مــن ذوي النفــوذ الواســعة وبعــد‬\n      ‫مكوثهــا ثالثــة أيــام بلياليهــا يف الفنــدق وهــي يف حيازتهــا إال أنهــا‬\n      ‫اضطــرت اخلــروج حلالتهــا الصحيــة التــي تدهــورت بســبب الضغوطــات‬\n      ‫التــي حتملتهــا مــن ذوي النفــوذ مبكــة وتوجهــت إلــى املستشــفى لســوء‬\n\n\n‫‪283‬‬\n\f‫حالتهــا وانتهــزوا الفرصــة اجلبابــرة فرصــة مغادرتهــا واســتعملوا نفوذهــم‬\n‫وجميــع أســاليبهم الغيــر ال أخالقيــة ودخلوا الفنــدق بجبابرتهم ونفوذهم‬\n‫ورفضــوا تســليمها العــن ومــا ملوكلتــي حيلــة إال إن اضطــرت  برفــع‬\n‫قضيــة اإلخــاء علــى املدعــي عليــه  منــذ ســنة تقريبــا مســتند(‪.))5‬‬\n‫وجوابــي ياصاحــب الفضيلــة علــى مــا قالــه زميلــي حفظــه اهلل وكيــل‬\n‫املدعــي عليــه بأنــي لــم أعطــه املســتند ســامحني وســامحه اهلل هــو أنــي‬\n‫نفــذت مــا أمــرت بــه مــن فضيلتكــم باحلــرف الواحــد ولــم أجتــرأ أن أزيــد‬\n‫عليــه حيــث أن فضيلتكــم أمرمتونــي بإعطائــه الالئحــة محــررة فقــط‬\n‫فأعطيتــه ولــم أتوقــع منــه أن يطلــب منــي صــورة مــن املســتند ألن أغلــب‬\n‫الظــن واملتوقــع أن موكلــه قــد زوده بالعقــود وبصــره علــى جميــع احلقائــق‬\n‫كأبســط األمــور عقــد االيجــار ة ‪ ،‬وأمــا قــول زميلــي جــزاه ربــي خيــر‬\n‫اجلــزاء أن موكلتــي تريــد إطالــة أمــد النــزاع وإحلــاق الضــرر فهــذا قــول‬\n‫يف غيــر محلــه ألنــه ال ميكــن ألي عاقــل أو جاهــل أن يحــدد مــن هــو‬\n‫املســتفيد مــن إطالــة النــزاع موكلتــي املدعيــة (‪ )......‬التــي تطالــب‬\n‫وتتضــرر وترجــوا وتســتغيث بالقضــاء بطلــب اإلخــاء منــذ ســنة تقريبــا‬\n‫ولهــا أحقيــة احليــازة بتاريــخ ‪1431/1/3‬هــ  أم املدعــي عليــه (‪ )......‬الــذي‬\n‫يتمتــع ويلهــو باغتصــاب العــن طيلــة هــذه الفتــرة وال يبالــي مــا تســبب بــه‬\n‫مــن ضــرر بإطالــة هــذا النــزاع بإبــرازه عقــود باطلــة ال صفــة لهــا البتــة ‪.‬‬\n‫وأمــا مــا قالــه زميلــي الكــرمي أيضــا أن إثــارة اإلشــاعة يكســر قيمتــه‬\n‫الســوقية أعتقــد أن هــذا القــول ال يصــدر عــن فهيــم أو لبيــب أوفقيــه ‪،‬‬\n‫فهــل يعقــل أن يبخــس صاحــب امللــك ملكــه ‪ ،‬وهــل يعقــل أن يبخــس‬\n‫صاحــب العــن عينــه بــأن ينقــص إيــراده وإيجــاره ‪ ،‬وهــل يرغــب صاحــب‬\n‫الســلعة أن يكــون ســلعته أردى مــن ســلعة غيــره ‪ ،‬وماهــي إال ســلعة مــن‬\n\n\n                                                                                       ‫‪284‬‬\n\f      ‫ســلع الدنيــا يتداولهــا األيــام وســلعة اهلل هــي الغاليــة وجوابــي يف قولــه‬\n      ‫(أوالً) صاحــب الفضيلــة أفيدكــم بــأن عقــد ‪ ...‬لتشــغيل الفندق للمدعي‬\n      ‫عليــه ‪ /‬الــذي يبــدأ بتاريخ‪1431/1/1‬ه ـ ليــس لــه صفــة ألن يف ذلــك‬\n      ‫الوقــت ليــس لــه أحقيــة إبــرام عقــود التأجيــر والتشــغيل كــون موكلتــي‬\n      ‫هــي مالكــة املنفعــة يف وقتهــا ويف الوقــت احلالــي ‪ ،‬فإنــه يعتبــر بذلــك‬\n      ‫تصــرف ‪ ...‬عليــه تصرفــا باطــا ألنــه ســبق أن قــام بتأجيــر الفتــرة الباقيــة‬\n      ‫مــن أربعــة عشــرة ســنة مــن اإلســتثمار ملوكلتــي (‪ )........‬مبوجــب العقــد‬\n      ‫املبــرم بينهمــا الــذي يبــدأ بتاريــخ ‪1428/1/1‬ه ـ وينتهــي بانتهــاء الفتــرة‬\n      ‫الباقيــة مــن االســتثمار بتاريــخ ‪1440/12/30‬ه ـ املصــدق مــن الغرفــة‬\n      ‫التجاريــة بســند رقــم ‪ 798458‬بتاريــخ ‪1429/02/20‬ه ـ وتنــازل بــكل‬\n      ‫نشــاطاته ومطبوعاتــه وعــدل الســجل بفــرع وزارة التجــارة بإســم‬\n      ‫موكلتــي بســند رقــم ‪60394‬بتاريخ‪1428/3/13‬هــ  مســتند رقــم (‪)4‬‬\n      ‫صاحــب الفضيلــة حســب مــا أعلــم أن عقــد بالتشــغيل أننــي كنــت‬\n      ‫شــاهدا  عليــه وأنــا مــن قمــت بتســليمه للمدعــي عليــه يف بيتــه مــع‬\n      ‫وكيــل‪ ...‬و‪ ...‬بتاريــخ ‪1430/11/29‬ه ـ ووقعــت امامــه كشــاهد وكان‬\n      ‫عقــد وقائــي واحتــرازي ألنهــم كانــوا يعانــون من اعتداءات علــى الفندق‬\n      ‫والعمالــة وكانــت مــن بــاب الفضــول ملســاعدتهم يف تشــغيل الفنــدق‬\n      ‫بعمالــة ‪  ...‬خلبرتهــم ســابقا ومعرفتهــم أوضــاع الفنــدق حســب طلــب‬\n      ‫وإحلاحــه عــدة مــرات وذلــك لكــف الضــرر واإليــذاء مــن الطامعــن‬\n      ‫واحملرضــن الذيــن آذ و العمالــة وأدخلــوا الرعــب يف قلوبهــم لكونهــم‬\n      ‫علــى كفالــة ‪ ....‬ولــم يتمكنــوا مــن التنــازل علــى موكلتنــا لضيــق‬\n      ‫الوقــت وبعــد فتــرة كلمنــي املدعــي عليــه إن عقــد التشــغيل ضعيــف‬\n      ‫اليحــل محــل عقــد اإليجــار والينفعنــا بشــيء إال إن يكــون عقد احترازي‬\n\n\n‫‪285‬‬\n\f  ‫ووقائــي‪ ،‬وان عقــد اإليجــار ضــروري يضمــن حقــوق الطرفني وال يعترف‬\n  ‫إال بــه يف الدوائــر احلكوميــة للمعامــات الرســمية ‪ ،‬وطلــب منــا إن جنــد‬\n  ‫د لــه عقــد اإليجــار مــن موكلتــي لضمــان حقوقــه ألن موكلتــي هــي مــن‬\n  ‫إســتلمت منــه املبالــغ لكونهــا هــي مالكــة املنفعــة ولعلــه علــم إن عقــد‬\n  ‫التشــغيل ليــس لــه صفــة واستشــرت احملامــي وكلمــت زوج موكلتــي‬\n  ‫وجدد له العقد الذي يبدأ يف ‪1431/1/3‬هـ وينتهي يف‪1431/12/30‬هـ‬\n  ‫مســتند رقــم (‪ )3‬موقعــة ومختومــة مــن بطوعــه وبرغبتــه واختيــاره أي‬\n  ‫كليــا نقضــه وإبــرازه‬‫ً‬         ‫بعــد ثالثــة أيــام مــن عقــد التشــغيل وهــذا ينــايف‬\n‫عقــد التشــغيل وهــو يعلــم علــم اليقــن أنــه اســتلم الفنــدق مــن موكلتــي  ‬\n  ‫ـميا حســب اجلــرد ووقــع علــي ســندات اســتالمه الفنــدق‬       ‫وتســلم منهــا رسـ ً‬\n  ‫وبــدوره ســلم املبالــغ لوكيلنــا طيلــة هــذه الفتــرة حســب الشــيكات‬\n  ‫مســتند رقــم (‪ )2‬وموكلتــي املتضــررة هــي مــن تطالبــه باإلخــاء وتســليم‬\n  ‫العــن ودفــع املثــل منــذ ســنة تقريبــا وليــس الــذي ليــس لــه أي صفــة اآلن‬\n  ‫‪ ،‬وإظهــار هــذا العقــد وإبــرازه ال يوجــد لــه إال تفســير واحــد يــا صاحــب‬\n  ‫الفضيلــة وهــو تعطيــل احلكــم وتضليــل العدالــة وتأخيــر احلكــم قــدر‬\n  ‫اإلمــكان وكســب الوقــت إلــى أن انتهــي ســنة تلــو الســنة ويبــدؤوا‬\n  ‫البحــث إلــى طــرق جديــدة ال أخالقيــة مــع بدايــة ســنة جديــدة وإدخالنــا‬\n  ‫يف معمعــة ســنة أخــرى مــع مغتصــب جديــد ومخــادع جديــد واهلل أعلــم‬\n  ‫بالســرائر ‪ ،‬وأزيدكــم ياصاحــب الفضيلــة برهان ـ ًا وتبيان ـ ًا وأشــير إلــى‬\n  ‫نقطة هامة وهي يوم أن ادعى على باإلخالء بتاريخ ‪1430/10/27‬برقم‬\n  ‫‪ 31/100749‬وتدخلــت موكلتــي باعتــراض لكونهــا هــي مالكــة‬\n  ‫املنفعــة واملؤجــرة للمدعــي عليــه ويف يومهــا ليــس للمدعــي عليــه  أال أن‬\n  ‫يبــرز عقــد موكلتــي  (‪ ).......‬علــى أنهــا كدليــل ومبوجــب هــذا العقــد‬\n\n\n                                                                                              ‫‪286‬‬\n\f      ‫صرفتــم النظــر فضيلتكــم بحكمتكــم عــن دعــوى ألنــه ال ميلــك أي‬\n      ‫صفــة فكيــف يدعــون اآلن أنهــم لــم يســتأجروا مــن إن دل علــى شــيء‬\n      ‫فهــو يــدل علــى أن هنــاك مــن يتواطئــون خلــف الســتار مــع املســتثمر علينــا‬\n      ‫إلخراجنــا مــن العــن وإبطــال العقــد بــأي صــورة كانــت ‪ ،‬وجوابــي يف‬\n      ‫قولــه (ثانيـاً) عــن عقــد التنــازل عــن الفنــدق بــن الطــرف األول مؤسســة‬\n      ‫والطــرف الثانــي املبــرم بتاريــخ ‪1431/10/9‬ه ـ والــذي يبــدأ اســتثماره‬\n      ‫من‪1432/1/1‬ه ـ وينتهــي بتاريخ‪1440/12/30‬ه ـ أقــول وبــكل أســف‬\n      ‫أن هــذا العقــد باطــل وليــس لــه أي صفــة وال ميلــك أحقيــة إبــرام عقــود‬\n      ‫اإليجــار وال التنــازل ألنــه ســبق إن الطــرف األول ‪ ......./‬أجــر الفتــرة‬\n      ‫الباقيــة مــن عقــد االســتثمار لألســتاذ ‪......... /‬وهواربعــة عشــرة ســنة‬\n      ‫يبــدأ يف ‪1427/5/19‬ه ـ وينتهــي بانتهــاء عقــد اإلســتثمار يف‬\n      ‫‪1440/12/30‬ه ـ مبوجــب العقد املبــرم بتاريخ ‪1427/5/12‬هـ واملفصل‬\n      ‫تفصيــا كامــا دقيق ـ ًا عــن كيفيــة الدفعــات يف الســنوات األربعــة‬\n      ‫عشــر املذكــورة مــن االســتثمار واملصــدق مــن الغرفــة التجاريــة يف‬\n      ‫‪2006/6/27‬م بســند رقــم ‪4954666‬مــن الريــاض وكان الطــرف األول‬\n      ‫مخيـ ٌـر بــن أمريــن إمـ ّا أن يتنــازل أو أن يقــوم بتأجيــر الفتــرة الباقيــة مــن‬\n      ‫اإلســتثمار مبوجــب التنــازل التــي أعطــي لــه مــن صاحــب اإلســتثمار مــن‬\n      ‫مجموعــة ‪ ...‬بتاريــخ ‪1427/5/18‬ه ـ فاختــار أحــد األمريــن وقــام بتأجيــر‬\n      ‫الفتــرة الباقيــة مــن اإلســتثمار لألســتاذ‪ ........‬وأعطــي لــه تنــاز ًال أيض ـ ًا‬\n      ‫بتصريــح احلــج مــن مجموعــة وبذلــك يظهــر لفضيلتكــم أن الطــرف‬\n      ‫األول أواملدعــو ال ميلكــون املنفعــة وال الصفــة يف إبــرام العقــود مســتند‬\n      ‫رقــم (‪ .)5‬وجوابــي يف قولــه (ثالثــا) أيضــا عــن عقــد إيجــار (فنــدق ‪)...‬‬\n      ‫لعام‪1432‬ه ـ واملبــرم بــن الطــرف األول والطــرف الثاني ملدة عام كامل‬\n\n\n‫‪287‬‬\n\f‫الــذي يبــدأ من‪1432/1/1‬ه ـ وينتهــي بتاريخ‪1432/12/30‬ه ـ وأقــول‬\n‫بــكل أســف ايضــا أن هــذا العقــد باطــل وليــس لــه أي صفــة وال يخفــى‬\n‫علــى فضيلتكــم أن مــا بنــي علــى باطــل فهــو باطــل ألنــه بنــي هــذا العقــد‬\n‫علــى تنــازل الــذي ليــس لــه صفــة وال ميلــك املنفعــة يف إبــرام العقــود‬\n‫أوالتنــازل ألن فاقــد الشــيء ال يعطيــه‪ .‬صاحــب الفضيلــة كل هــذه‬\n‫العقــود التــي أظهرهــا وكيــل املدعــي عليــه باطلــة وليــس لهــا أي صفــة‬\n‫البتــة لكــون أن موكلتــي هــي مالكــة املنفعة حاليا ومســتقبال مبشــيئة‬\n‫اهلل وهــي التــي متلــك الصفــة وأحقيــة إبــرام عقــود التأجيــر مبوجــب‬\n‫العقــد الــذي لديهــا مســتند رقــم (‪ . )4‬صاحــب الفضيلــة اضطــر إلــى إن‬\n‫ألفــت أنظاركــم إلــى بعــض األمــور التــي جــرت خلــف الســتار لكــي‬\n‫يتضــح لكــم الصــورة جليــا حلســم هــذا األمــر ‪ ،‬وأزيدكــم برهانــا‬\n‫وتبيانــا علــى إتباعهــم األســاليب الغيــر الأخالقيــة وطرقهــم امللتويــة‬\n‫وإصرارهــم علــى إغــراء املدعــي عليــه لكســب تواطئــه لعــدم تســليم‬\n‫العــن ملوكلتــي وهــي‪ :‬أوال‪ :‬أن العقــد الــذي ابرمــه املدعــو التــي ليــس‬\n‫لهــا صفــة مــع املدعــي عليــه والــذي مت بتاريــخ ‪1431/11/6‬ه ـ أي قبــل‬\n‫شــهر تقريبــا مــن انتهــاء عقــد موكلتــي وتســليمها العــن مــن قبــل‬\n‫مســتأجرها املدعــي عليــه وســلم املدعــي عليــه مبلــغ مليــون وثالثمائــة‬\n‫وخمســون ألــف ريــال  مبوجــب اإلقــرار املوقــع مــن مجموعــة املــؤرخ‬\n‫يف‪1431/10/16‬هـ أي قبل شــهرين من انتهاء عقد موكلتي وتســليمها‬\n‫العــن وعلــى مطبوعاتــه اخلــاص بالتزامــه بســداد قيمــة الشــيك مببلــغ‬\n‫مليــون وثالثمائــة وخمســون ألــف ريــال لصالــح يعتبــر فيــه ضامنــا يف‬\n‫هــذا العقــد حســب إقــراره يف مســتند ه رقــم (‪ )6‬العقــد يف الفقــرة الرابعة‬\n‫يف شــروط عامــة مبــا ذا نفســر هــذا اإلقــرار يــا صاحــب الفضيلــة علــى‬\n\n\n                                                                                     ‫‪288‬‬\n\f        ‫ـيء خلــف‬‫مــاذا يــدل هــذا اإلقــرار وهــذا الضمــان يــدل علــى أن هنــاك شـ ٌ‬\n        ‫الســتار أعطــي هــذا اإلقــرار للمدعــي عليــه وذلــك حتريض ـ ًا وتغريـ ًـرا‬\n        ‫لعــدم إخالئــه العــن وتســليم املبنــى ملوكلتــي وهنــاك الكثيــر مــن‬\n        ‫الترغيــب والتغريــر يف مســتنده للمدعــي عليــه منهــا بــان يكــون لــه حــق‬\n        ‫الشــفعة يف التجديــد وأيضــا غــرر بتخفيــض القيمــة االيجاريــة وإضافــة‬\n        ‫احملــات التجاريــة التــي لــم يكــن مضافــا يف عقــده مــع موكلتــي فــإن‬\n        ‫دل فإنــه يــدل علــى أن هنــاك مــن يتآمــر ويخــادع ويغــرر ويتواطــأ خلــف‬\n        ‫الســتار ولذلــك ســيجد فضيلتكــم يف الفقــرة اخلامســة يف مســتنده أنــه‬\n        ‫أســقط الطرفــان دعــوا (الغــن والغــرر واجلهالــة حــاال ومســتقبال)  فــإن‬\n        ‫لــم يكــن هنــاك خلــف الســتار شــيء مــن هــذا فمــا الداعــي لكتابــة هــذه‬\n        ‫الفقــرة  والــذي يدعــي أنــه ســلم العــن للمدعــي عليــه بعــد أن عاينــه‬\n        ‫املذكــور طبــق رغبتــه (ووافــق علــى أوضاعهــا  نهائيــا وال يحــق لــه‬\n        ‫االعتــراض علــى ذلــك الحقــا) االيظهــر لفضيلتكــم أن يف هذه العبارات‬\n        ‫أن تســليم العــن لــم يتــم قــط ولــم يســلم بالطريقــة الصحيحــة املعروفــة‬\n        ‫حســب اجلــرد ومتكــن املســتأجر ولعــل هــذا يــدل علــى أن هنــاك مــن‬\n        ‫غــرر وتواطــؤ مــع مــن يدعــي انــه أجــره وســلمه وإال مــا كان بحاجــة إلــي‬\n        ‫هــذه العبــارات املبهمــة وكتابتهــا بهــذه الطريقــة وكل هــذا إلخــراج‬\n        ‫موكلتــي مــن العــن بطريقــة ملتويــة وإبطــال عقدهــا التــي متلــك مبوجبها‬\n        ‫الفتــرة الباقيــة مــن االســتثمار ‪ .‬وال يخفــي علــى فضيلتكــم عندمــا‬\n        ‫ارتفعــت اإليجــارات دخــل الطمــع يف القلــوب  وشــاء املولــى العلــي القديــر‬\n      ‫ســبحانه بقدرتــه أن يجعــل قســمة للضعفــاء واملســاكني مــن أغنيائهــم  ‬\n        ‫‪ ،‬فطلــب املؤجــر الــذي اجــر للمدعــو العــن املذكــورة عقــد أربعــة عشــرة‬\n        ‫ســنة املــدة الباقيــة مــن االســتثمار إلبــرام عقــد جديــد بســعر جديــد‬\n\n\n‫‪289‬‬\n\f  ‫وباتفــاق جديــد فرفــض املســتأجر الــذي لديــه عقــد أربعــة عشــرة ســنة‬\n  ‫الفتــرة الباقيــة مــن االســتثمار عقــد ســاري صريــح وبشــروط صريحــة‬\n  ‫وواضحــة واملفصــل فيــه تفصيــا كامــا دقيقـ ًا عــن كيفيــة الدفعــات‬\n  ‫يف الســنوات الباقيــة املذكــورة مــن االســتثمار للخضــوع واإلذعــان‬\n  ‫ألوامرهــم وطرقهــم امللتويــة الغيــر محببــة للنفــوس البشــرية ‪ ،‬ومنــذ ذلــك‬\n  ‫اليــوم ياصاحــب الفضيلــة بــدأت هــذه األالعيــب اخلفيــة بأســاليب غيــر ال‬\n  ‫أخالقيــة وطــرق غيــر شــرعية وقبــل ســنتني تقريبــا ياصاحــب الفضيلــة‬\n  ‫أرســلوا إلينــا رجــا يقــال لــه ‪ ....‬ادعــى انــه ومعــه مجموعــة مــن األشــداء‬\n  ‫واألقويــاء مــن أهــل وزعمــوا إنهــم قــد دفعــوا واشــتروا االســتثمار وقامــوا‬\n  ‫باإلعتــداء ليــا علــي الفنــدق ودخلــوه عنــوة وضربــوا العمــال ويف ســاعته‬\n‫قــام وكيلنــا الشــيخ باســتدعاء الشــرطة بتاريــخ  ‪ 1430/3/19‬هجــري  ‬\n  ‫بشــرطة اجيــاد يف الســاعة الثانيــة عشــرة ليــا وأخذتهــم وحققــت معهــم‬\n  ‫الشــرطة واخــذ عليهــم تعهــد بعــدم التعــرض وأحيلــوا لالدعــاء والتحقيــق‬\n  ‫حســب كالم الضابــط‪ ،‬وبعــد هــا ســكتوا فتــرة ثــم يف الســنة التاليــة‬\n  ‫أرســلوا فرقــة اخــرى يزعمــون إنهــم أيضــا أن لديهــم عقــد وقــد اشــتروا‬\n  ‫االســتثمار لكنهــم تفهمــوا الوضــع ورجعــوا عــن كيدهــم ولــم يرغبــوا‬\n  ‫يف الظلــم وســلب احلقــوق بالباطــل وهكــذا دواليــك ياصاحــب الفضيلــة‬\n  ‫يأتــون ويزعمــون كل فتــرة وفتــرة بحجــج واهيــة وعقــود باطلــة الصفــة‬\n  ‫لهــا ويتســببون الضــرر ملوكلتــي ‪ ،‬ويف هــذه الفتــرة ياصاحــب الفضيلــة‬\n  ‫فوجئنــا بأنهــم أرســلوا إلينــا هــذه املــرة بأنــاس متمرســن ومحنكــن‬\n  ‫مختصــن يف قضايــا املنطقــة املركزيــة لكــي يتمكنــوا مــن إبطــال‬\n  ‫عقــد موكلتــي  وإخراجهــا مــن العــن بالغــرر وبالتواطــؤ مــع املدعــي‬\n  ‫عليــه  وبعمــل عقــد بينهمــا وقبــض الثمــن قبــل انتهــاء عقدنــا مــع املدعــي‬\n\n\n                                                                                        ‫‪290‬‬\n\f        ‫عليــه بشــهرين والهــدف اإليقــاع بــن املســتأجر واملؤجــر واالســتفادة‬\n      ‫برفــع دعــوي مدروســة علــي املدعــي عليــه باتفاقهمــا مســبق ًا علــى الصلــح  ‬\n        ‫بينهمــا ألجــل أن يفــرض صفــة التملــك ‪ ،‬ولكــن ياصاحــب الفضيلــة‬\n      ‫بحكمتكــم صرفتــم النظرعــن الدعــوي ببقــاء املســتأجر احلالي بالعني ‬\n        ‫وبعــدم إعطــاء صفــة التملــك وبذلــك متكنــوا مــن واحــدة وهــي إبقــاء‬\n        ‫املدعــي عليــه يف العــن إلــي هــذا اليــوم ولــم يتمكنــوا مــن الثانيــة وهــي‬\n        ‫فــرض صفــة التملــك وميكــرون وميكــر اهلل واهلل خيــر املاكريــن ‪،‬‬\n        ‫صاحــب الفضيلــة اســتعملوا جميــع األســاليب واحليــل والنفــوذ  بالطــرق‬\n        ‫امللتويــة الغيــر احملببــة للنفــوس البشــرية بإخراجنــا مــن العــن املذكــورة‬\n        ‫وإفســاد عقدنــا اجلــاري ملــدة التســع الســنوات املقبلــة لكــن اهلل ســبحانه‬\n        ‫وتعالــي رحيــم بعبــاده جعــل كيدهــم فيهــم إلــي يومنــا هــذا وفضــح‬\n        ‫مكرهــم وخدعهــم لقولــه تعالــي (وان يريــدوا أن يخدعــوك فــان حســبك‬\n        ‫اهلل هــو الــذي أيــدك بنصــره وباملؤمنــن ‪  )....‬واهلل اعلــم إن كان هنــاك‬\n        ‫مؤامــرة وخــداع وتواطــؤ مــن طــرف اوأطــراف واهلل يتولــي الســرائر‪،‬‬\n        ‫وجتارتنــا املتواضعــة يــا صاحــب الفضيلــة للتعفــف وابتغــاء ماعنــد اهلل‬\n        ‫مــن بــاق ‪ ،‬وال نقــول إال علــي مــن ظلمنــا حســبنا اهلل ونعــم الوكيــل ومــا‬\n        ‫توفيقــي إال بــاهلل عليــه واليــه أنيــب ‪،‬صاحــب الفضيلــة ال ملجــأ وال‬\n        ‫منجي من اهلل إال إليه  جلأنا إلي اهلل  ثم إلي باب عدلكم وإنصافكم‬\n        ‫بــأن تنظــروا يف طلبنــا بعــن العــدل واإلنصــاف واالنســانية إللــزام املدعي‬\n        ‫عليــه بإخــاء العــن وتســليمه لنــا كمــا اســتلمه منــا حســب اجلــرد‬\n        ‫ومبوجــب البنــد احلاديــة عشــر يف العقــد فــورا ودون مماطلــة وعــدم‬\n        ‫تســليمه للغيــر وان قــام بتســليمه للغيــر ســيكون مفرط ـ ًا ومتواطئ ـ ًا ‪،‬‬\n        ‫والتعهــد بذلــك خطيــا أمــام فضيلتكــم هكــذا قــال ‪ .‬وبعــرض ذلــك‬\n\n\n‫‪291‬‬\n\f‫علــى املدعــى عليــه وكالــة أجــاب قائــا إنــي أطلــب مهلــه لالستفســار‬\n‫مــن موكلــي ومــن ثــم أجيبكــم ويف يوم االحــد ‪1433/3/27‬هـ افتتحت‬\n‫اجللســة وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه و ال مــن‬\n‫ميثلــه ثــم ســألت املدعــي وكالــة هــل لديــه البينــة علــى دعــواه فأجــاب‬\n‫قائــا نعــم لــدي البينــة عليهــا ثــم أبــرز مــن يــده عقــد اتفــاق بــن طرفــن‬\n‫بايجــار فنــدق ‪  ...‬ومــدون أعــاه مجموعــة ‪ ...‬ويتضمــن مــن املقدمــة مــا‬\n‫يلــي ((احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وعلــى‬\n‫آلــه وصحبــه وبعــد ففــي تاريــخ ‪1430/1/1‬هـ بعــون اهلل تعالى مت االتفاق‬\n‫بيننــا نحــن الطــرف األول ‪ ........:‬ســعودية اجلنســية رقــم الســجل املدنــي‬\n‫رقــم (‪ )......‬تاريخهــا ‪1401/12/20 :‬ه ـ الصــادرة مــن الريــاض وميثلهــا‬\n‫الوكيــل الشــرعي ســعودي اجلنســية رقــم البطاقــة (‪ )........‬مبوجــب‬\n‫وكالــة رقــم (‪ )2/34‬بتاريــخ ‪1428/11/17‬ه ـ مجلــد ‪ 788‬وعنوانــه يف‬\n‫هــذا العقــد فنــدق ‪  ...‬ت ‪ :‬فاكــس ‪( :‬املؤجــر) الطــرف الثانــي ‪... :‬‬\n‫ســعودي اجلنســية رقــم الســجل املدنــي (‪ )......‬وعنوانــه يف هــذا العقــد ‪...‬‬\n‫شــارع ‪  ...‬ج ت‪ ،...‬فاكــس ‪ ...‬ص ب ‪ ( ...‬املســتأجر) علــى إيجــار (فنــدق‬\n‫‪ ) ...‬ملــك وقــف بجــوار ‪ ...‬شــارع ‪  ...‬ومت االتفــاق علــى مــا يلــي ‪ :‬أوال ‪ :‬مبــا‬\n‫أن الطــرف األول يعتبــر صاحــب العــن املذكــورة مبوجــب العقــد الــذي‬\n‫لديــه و ال يوجــد هنــاك أي موانــع يف بنــود التأجيــر للغيــر أو التنــازل عنــه‬\n‫فقــد رغــب الطــرف الثانــي يف اســتئجارها مــن تاريــخ ‪1430/1/1‬ه ـ الــى‬\n‫‪1430/12/30‬ه ـ فوافــق الطــرف األول علــى ذلــك وحصــل اإليجــاب‬\n‫والقبــول يف هــذا العقــد حســب بنــوده املدونــة أدنــاة ‪ .‬ثانيــا ‪ :‬أجــر الطــرف‬\n‫األول علــى الطــرف الثانــي العــن املبينــة أعــاه واملعبــر عنهــا فيمــا بعــد‬\n‫(العــن املؤجــره) ووافــق الطــرف الثانــي علــى ذلــك بغــرض اســتعمالها يف‬\n\n\n                                                                                          ‫‪292‬‬\n\f      ‫االغــراض املشــروعة وفــق اســتخدامات تصميــم العمــارة مبــا ال يتعــارض‬\n      ‫مــع مــا تقــرره اجلهــات والســلطات ‪ .‬ثالثــا ‪ :‬يقــر الطــرف الثانــي إقــرار ال‬\n      ‫رجــوع فيــه بأنــه قــد عايــن العــن املؤجــرة معاينــة تامــة ودقيقــة ونافيــة الي‬\n      ‫جهالــة ووجدهــا يف حالــة ســليمة وجيــدة وصاحلــة لالســتخدام ‪ .‬رابعــا ‪:‬‬\n      ‫مــدة هــذه العقــد تبــدأ مــن ‪1430/1/1‬ه ـ وتنتهــي يف ‪1430/12/30‬ه ـ‬\n      ‫ويتجــدد العقــد تلقائيــا بعقــد جديــد لعــام ‪1431‬ه ـ بشــرط أن يتــم دفــع‬\n      ‫الدفعــة األولــى لعــام ‪1431‬ه ـ حســب الســنة األولــى وإعطــاء شــيكات‬\n      ‫للدفعــات الباقيــة لعــام ‪1431‬ه ـ وكمثلهــا لعــام ‪1432‬ه ـ يتجــدد تلقائيــا‬\n      ‫بعقــد جديــد إذا مت دفــع الدفعــة األولــى حســب التواريــخ املذكــورة‬\n      ‫للســنة التــي قبلهــا واال يلغــى العقــد تلقائيــا ويحــق للطــرف األول حيــازة‬\n      ‫الفنــدق بتاريــخ ‪1431/1/3‬ه ـ وكمثلهــا لعــام ‪1432‬ه ـ مــع أثنــن مــن‬\n      ‫الشــهود وبحضــور الوكيــل يعمــل محضــر بجــرد الفنــدق إذا لــم يتــم دفــع‬\n      ‫الدفعــة األولــى للســنوات املذكــورة و ال يحــق للطــرف الثانــي االعتــراض‬\n      ‫علــى ذلــك كمــا ال يحــق لــه أن يخــرج مــن أثاثــات الفنــدق أي شــيء اال‬\n      ‫بعــد تســليم الفنــدق للطــرف األول حســب اجلــرد التــي عملت عند اســتالم‬\n      ‫الطــرف الثانــي الفنــدق ‪ .‬خامســا ‪ :‬قيمــة االيجــار هــي مبلــغ ( ‪)1300000‬‬\n      ‫مليــون وثالثمائــة ألــف ريــال فقــط يدفــع علــى النحــو التالــي مبلــغ (‬\n      ‫‪ )650000‬ســتمائة وخمســون ألــف ريــال بشــيك رقــم (‪ )....‬علــى بنــك ‪...‬‬\n      ‫باســم الوكيــل الشــرعي املذكــور بالعقــد عنــد توقيــع العقــد ويدفــع‬\n      ‫الدفعــة الثانيــة بتاريــخ ‪1430/7/15‬ه ـ مبلغ وقــدره ( ‪ )350000‬ثالثمائة‬\n      ‫وخمســون الــف ريــال بشــيك رقــم (‪ . )000190‬ويدفــع الدفعــة الثالثــة‬\n      ‫بتاريــخ ‪1430/9/15‬ه ــمبلغ وقــدره ( ‪ )300000‬ثالثمائــة ألــف ريــال‬\n      ‫فقــط بشــيك رقــم (‪ )000191‬أقصــاه ويدفــع الســنوات التاليــة حســب‬\n\n\n‫‪293‬‬\n\f‫التواريــخ املذكــورة للســنة األولــى يف العقــد ‪ .‬سادســا‪ :‬يتعهــد املســتأجر‬\n‫بســداد األجــرة يف املواعيــد احملــددة يف هــذا العقــد وإذا تأخــر عــن‬\n‫الســداد مــدة اســبوع مــن تاريــخ االســتحقاق فللمؤجــر احلــق يف إخالئــه‬\n‫مــن العــن املؤجــرة فــورا بــدون أي قيــد أو شــرط ويصبــح املســتأجر‬\n‫مســؤوال عــن جميــع مــا يترتــب علــى ذلــك مــن مصاريــف ‪ .‬ســابعا يتحمــل‬\n‫املســتأجر مــن تاريــخ اســتالمه للعــن املؤجــرة مســؤولية اســتخراج‬\n‫التصاريــح والتراخيــص الالزمــة ودفــع كافــة الرســوم واالســتيفاءات‬\n‫احلكوميــة كاالســتخبارات واملباحــث اجلنائيــة والغرفــة التجاريــة وجلنــة‬\n‫إســكان احلجــاج وهيئــة الســياحة والدفــاع املدنــي وغيرهــا مــن اجلهــات‬\n‫ذات العالقــة مهمــا كان نوعهــا واملقــررة علــى العــن املؤجــرة ‪ .‬ثامنــا أن‬\n‫قيمــة رســوم اســتهالك الكهربــاء واملــاء واملنافــع واخلدمــات األخــرى‬\n‫التــي تقــدم الــى املســتأجر فيمــا يتعلــق بالعــن املؤجــرة تقــع علــى عاتــق‬\n‫املســتأجر بكاملهــا مــن تاريــخ هــذا العقــد ويف حالــة إخــاء املســتأجر‬\n‫للعــن املؤجــرة عليــه إحضــار مخالصــات تفيــد بدفهــة جميــع رســوم هــذه‬\n‫اخلدمــات ‪ .‬تاســعا ‪ :‬تســري قيمــة االيجــار املوضــح اعتبــارا مــن تاريــخ بــدء‬\n‫ســريان مــدة العقــد ســواء اســتفاد املســتأجر مــن العــن أو لــم يســتفد ‪.‬‬\n‫عاشــر ًا ‪ :‬هــذا العقــد شــخصي للمســتأجر املبــن أســمه يف هــذا العقــد و‬\n‫ال يجــوز التنــازل عنــه للغيــر أو تأجيــر كل أو بعــض املــكان مــن الباطــن‬\n‫و ال مانــع مــن تأجيــره للــزوار واملعتمريــن واجلروبــات والبعثــات احلــادي‬\n‫عشــر ‪ :‬ال يجــوز للمســتأجر تغييــر معالــم املكان املؤجــر عليه أو واجهته‬\n‫اخلارجيــة إال إذا وافــق املؤجــر علــى ذلــك خطيــا ومبصاريــف علــى عاتــق‬\n‫املســتأجر وكل تغييــر أو إضافــات يف العــن املؤجــر تصبــح ملــكا‬\n‫للمؤجــر عنــد انتهــاء هــذا العقــد بــدون مقابــل وال يجــوز إزالتهــا إال إذا‬\n\n\n                                                                                      ‫‪294‬‬\n\f      ‫طلــب املؤجــر ذلــك ومبصاريــف علــى عاتــق املســتأجر كل هــذا بــدون‬\n      ‫حــق مطالبــة الطــرف الثانــي للطــرف األول بــأي تعويــض مــا عدا األشــياء‬\n      ‫العينيــة احملمولــة واملســتجلبة مــن الطــرف الثانــي مثــل الهاتــف‬\n      ‫والكمبيوتــر باســتثناء األشــياء املذكــورة يف محضــر اجلــرد والتســليم‬\n      ‫املوقــع بــن الطرفــن ومــا اشــترط عليــه الطــرف األول يف بقــاءه الثانــي‬\n      ‫عشر ‪ :‬كافة األضرار التي قد تصيب األرواح أو العقار  أو املمتلكات‬\n      ‫اخلاصــة باملســتأجر أو اجليــران أو غيرهــم مــن أي ســبب كان أو مــن‬\n      ‫جــراء حريــق قــد ينشــب يف العــن املؤجــرة مــن أي ســبب كان يكــون‬\n      ‫املســتأجر وحــده مســؤوال عــن جميــع التعويضــات أو املســؤوليات املدنيــة‬\n      ‫بالكامــل الثالــث عشــر ‪ :‬إن املؤجــر غيــر مســؤول أمــام أي جهــة كانــت‬\n      ‫عــن أيــة أضــرار أو أخطــار قــد تقــع يف األرواح واألمــوال بســبب املصاعــد‬\n      ‫أو أســاك الكهربــاء أو ســقوط األمطــار أو انقطــاع املــاء أو الكهربــاء‬\n      ‫أو ألي ســبب آخــر وعلــى الطــرف الثانــي أن يتخــذ اإلجــراءات الالزمــة‬\n      ‫بنفســه أمــام جهــات اإلختصــاص وإصــاح مــا تعطــل وإعادتــه إلــى وضعه‬\n      ‫الطبيعــي فــورا وبــدون أي تأخيــر ودون أي انتظــار الفصــل يف أي دعــوى‬\n      ‫أو مطالبــة حيــال الغيــر بهــذه األضــرار الرابــع عشــر ‪ :‬إن املصاعــد‬\n      ‫الكهربائيــة ميــزة ممنوحــة مــن املؤجــر للمســتأجر بــدون مقابــل فــإذا‬\n      ‫توقفــت عــن العمــل ألي ســبب كان فــا يحــق للمســتأجر التوقــف عــن‬\n      ‫الســداد اإليجــار املســتحق عليــه أو طلــب تعويــض عــن ذلــك وعليــه‬\n      ‫صيانتهــا فــورا وعلــى املســتأجر إبــرام عقــود صيانــة مــع شــركة مختصة‬\n      ‫ســنويا علــى حســابه اخلــاص حســب طلبــات اجلهــات املختصــة اخلامــس‬\n      ‫عشــر ‪ :‬طــوال مــدة ســريان هــذا العقــد يحــق للطــرف األول أو أي مــن‬\n      ‫مندوبيــه يف الدخــول إلــى عــن املؤجــر للمعاينــة بإخطــار مســبق للطــرف‬\n\n\n‫‪295‬‬\n\f‫الثانــي ويلتــزم الطــرف الثانــي بذلــك الســادس عشــر ‪ :‬ليــس على الطرف‬\n‫األول أي مســؤولية مــن أي نــوع كانــت إذا تعرضــت العــن املؤجــرة أو‬\n‫تعــرض الطــرف الثانــي إلــى عمليــة مــن عمليــات الســرقة أو النصــب أو‬\n‫االحتيــال وعلــى الطــرف الثانــي أن يتخــذ التدابيــر الالزمــة ملنــع تعرضــه‬\n‫ملثــل هــذه العمليــات الســابع عشــر ‪ :‬يلتــزم الطــرف الثانــي بــأن يجــري‬\n‫علــى حســابه اخلــاص جميــع أعمــال الصيانــة الداخليــة للعــن املؤجــرة‬\n‫طــوال مــدة ســريان العقــد ويكــون مســؤال مســؤلية كاملــة إذا حــدث‬\n‫أي تلــف أو ضــرر للعــن املؤجــرة يف اإلصــاح والصيانــة أو عــدم تنفيــذ‬\n‫شــرط اجلــودة والنوعيــة يف أعمــال الصيانــة الالزمــة الثامــن عشــر  يحــق‬\n‫للطــرف األول فســخ العقــد يف احلــاالت التاليــة أ‪ /‬يف حالــة اســتعمال‬\n‫العــن املؤجــرة لغيــر الغــرض املســتأجر مــن أجلــه واملنصــوص عنــه يف‬\n‫هــذا العقــد ب‪ /‬إذا أخــل املســتأجر ولــم يلتــزم بالبنــد الســادس يف هــذا‬\n‫العقــد ج‪ /‬إذا أخــل املســتأجر ولــم يلتــزم بالبنــد العاشــر يف  هــذا العقــد‬\n‫التاســع عشــر ‪ :‬التــزم الطــرف الثانــي بتســليم املأجــور محــل هــذا العقــد‬\n‫للطــرف األول بحالتــه التــي كان عليهــا عنــد التعاقــد صاحلــا للســكن‬\n‫بكافــة معداتــه وأجهزتــه ومفروشــاته ومحتوياتــه الــواردة مبحضــر‬\n‫التســليم املرفــق بهــذا العقــد مــع مراعــاة نســبة االســتهالك املتعــارف‬\n‫عليهــا بخصــوص األثــاث واملفروشــات والتجهيــزات ومســتويف ملــا يلــزم‬\n‫مــن عمــل إصالحــات وصيانــة للســباكة والكهربــاء والنجــارة والدهــان‬\n‫واملصاعــد وخالفــه ممــا جــرت بــه العــادة يف مثيالتــه علــى أن يقــوم‬\n‫الطــرف الثانــي بتمكــن الطــرف األول مــن االطــاع علــى جميــع‬\n‫اإلصالحــات ويكــون تســليم املأجــور بعــد انتهــاء مــدة التعاقــد مبحضــر‬\n‫اســتالم يثبــت فيــه حالتــه عنــد التســليم ويف حــال ظهــور نقــص أو تلفيــات‬\n\n\n                                                                                    ‫‪296‬‬\n\f      ‫يف املبنــى أو جتهيزاتــه يلتــزم الطــرف الثانــي بإصالحهــا وإعادتهــا كمــا‬\n      ‫كانــت علــى حســابه اخلــاص العشــرون ‪ :‬يعتبــر عنــوان كل طــرف‬\n      ‫املوضــح قريــن اســمه يف هــذا العقــد موطنــا مختــارا فيمــا يتعلــق بتنفيــذ‬\n      ‫املراســات التــي تخــص هــذا العقــد مــا لــم يخطــر أحد الطرفــن الطرف‬\n      ‫اآلخــر كتابيــا بتغييــره احلــادي والعشــرون ‪ :‬اتفــق الطرفــان علــى أنــه لــو‬\n      ‫حصــل هــدد املؤجــر مــن قبــل احلكومــة فــإن الطــرف األول غيــر مســئول‬\n      ‫عــن ذلــك وحتســب األجــرة لصالــح الطــرف األول حتــى تاريــخ الهــدد‬\n      ‫مبوجــب محضــر رســمي بذلــك الثانــي والعشــرون ‪ :‬كل تغييــر يف‬\n      ‫شــروط هــذا العقــد ال يعتــد بهــا إال إذا كانــت بتوقيــع املؤجــر ومبوافقتــه‬\n      ‫اخلطيــة الثالــث والعشــرون ‪ :‬يف حــال امتنــاع الطــرف الثانــي عــن ســداد‬\n      ‫اإليجــار يحــق للطــرف األول أن يدخــل الفنــدق دون الرجــوع للطــرف‬\n      ‫الثانــي وعمــل محضــر بوجــود ثالثــة أشــخاص مــع وكيــل الطــرف األول‬\n      ‫وإثبــات مــا وجــد كمــا يحــق لــه أن يحجــز علــى جميــع مــا يكــون بالعــن‬\n      ‫املؤجــرة مــن مفروشــات ومنقــوالت وغيرهــا مــن املوجــودات وأن يتصرف‬\n      ‫يف كل مــا يكــون بالعــن املؤجــرة بالبيــع بالســعر الــذي يــراه مناســبا‬\n      ‫وأن يســتويف حقوقــه حيــال الطــرف الثانــي مــن حصيلــة البيــع وال يحــق‬\n      ‫للطــرف الثانــي أن يعتــرض علــى حجــز املوجــودات وال علــى ســعر بيعهــا‬\n      ‫وال علــى طريقــة البيــع وإذا لــم يــف ثمــن املوجــودات بحقــوق الطــرف‬\n      ‫األول فإنــه يكــون للطــرف األول احلــق مبطالبــة الطــرف الثانــي بكافــة‬\n      ‫املبالــغ املســتحقة الرابــع والعشــرون ‪ :‬مــن حــق الطــرف األول اســتالم‬\n      ‫املبنــى وحيازتــه بتاريــخ ‪1431/1/3‬ه ـ مبوجــب البنــد الرابــع دون الرجوع‬\n      ‫إلــى الطــرف الثانــي ودون موافقتــه ويف حالــة تأخــر احلجاج لســبب طارئ‬\n      ‫يعطــي الطــرف الثانــي مهلــة إلكمــال ترحيــل احلجــاج مبتابعــة وحضــور‬\n\n\n‫‪297‬‬\n\f  ‫الطــرف األول واســتالمه املبنــى مــع التــزام الطــرف الثانــي بتحمــل‬\n  ‫فواتيــر امليــاه والكهربــاء واخلدمــات طيلــة هــذه املهلــة والتــي ال تتعــدى‬\n  ‫عشــرة أيــام ‪ .‬اخلامــس والعشــرون ‪ :‬وافــق الطــرف الثانــي علــى بنــود هــذا‬\n  ‫العقــد بطوعــه واختيــاره والتــزم بالتقيــد مبوجبــه فــإن أخــل الطــرف‬\n  ‫الثانــي بشــيء مــن ذلــك فإنــه يحــق للطــرف األول إخــاء العــن بــدون قيــد‬\n  ‫أو شــرط ويصبــح العقــد الغيــا وللطــرف األول حــق املطالبــة فيمــا‬\n  ‫اســتخدمت فيــه العمــارة حتــى تاريــخ إلغــاء العقــد ‪ .‬الســادس والعشــرون‪:‬‬\n  ‫املطعــم غيــر داخــل يف اإليجــار وهــو مــن حق الطــرف األول وعلى الطرف‬\n‫الثاني إلزام املســتأجر بســداد (‪ )%10‬من قيمة فواتير املياه والكهرباء  ‬\n  ‫الســابع والعشــرون ‪ :‬يف حالــة بيــع االســتثمار ال قــدر اهلل مــن املســتثمر‬\n  ‫الرشــيد ينطبــق علــى الطــرف الثانــي مــا ينطبــق علــى الطــرف األول يف‬\n  ‫مــدة ســريان هــذا العقــد الثامــن والعشــرون ‪ :‬علــى الطــرف الثانــي عمــل‬\n  ‫ســيراميك يف الغــرف وجتديــد البويــة وعمــل جميــع مــا يلــزم مــن صيانــة‬\n  ‫شــاملة ويف حالــة أن الطــرف الثانــي غيــر الســرير القــدمي والثالجــات أو‬\n  ‫أي شــيء متحــرك قــدمي علــى الطــرف الثانــي إبقاؤهــا و ال يحــق لــه‬\n  ‫أخذهــا ألنهــا حلــت محــل القــدمي و ال يحــق لــه املطالبــة بــأي تعويــض يف‬\n  ‫أي حــال مــن األحــوال ‪ .‬التاســع والعشــرون ‪ :‬هــذا العقــد عقــد ملــزم‬\n  ‫للطرفــن ولورثتهمــا مــن بعدهــم ال يجــوز فســخه و ال إلغــاؤه إال بعقــد‬\n  ‫خطــي جديــد موقــع مــن الطرفــن وبغيــر ذلــك اليلتفــت إلــى أي تصــرف‬\n  ‫مــن أي مــن الطرفــن مهمــا كانــت األســباب إال مــا نصــت عليــه بنــود‬\n  ‫هــذا العقــد ‪ .‬وقــع الطرفــان هــذا العقــد وهمــا بكامــل أهليتهمــا‬\n‫الشــرعية غيــر مكرهــن و ال مجبريــن وكتــب هــذا العقــد نســختني ‬\n  ‫أصليتــن بيــد كل طــرف نســخة وحــرر يف ‪1430/1/8‬ه ـ وصلــى اهلل‬\n\n\n                                                                                      ‫‪298‬‬\n\f       ‫علــى نبينــا محمــد وعلــى الــه و صحبــه وســلم وبــاهلل التوفيــق ‪ )).‬ثــم‬\n       ‫ســألته هــل لديــه مزيــد بينــة علــى ذلــك فأجــاب قائــا نعــم لــدي زيــادة‬\n       ‫بينــة وأطلــب مهلــه إلحضارهــا هكــذا قــال ويف يــوم الثالثــاء‬\n       ‫‪1433/11/16‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر‬\n       ‫املتداعــون بالوكالــة ثــم ســألت املدعــي وكالــة ‪ ...‬عمــا طلــب ألجلــه يف‬\n       ‫اجللســة املاضيــة فأجــاب بقولــه أنــه ليــس لــدي أي بينــة ســوى العقــد‬\n       ‫هكــذا قــال و بعــرض ذلــك علــى املدعــى عليــه وكالــة إن ذلــك العقــد‬\n       ‫املبــرم بــن املدعيــة ‪ ...‬وبــن موكلــي عقــد صــوري وذلــك ألجــل إكمــال‬\n       ‫إجراءاتهــم اخلاصــة بلجنــة املســاكن بــوزارة احلــج وأطلــب مخاطبتهــم‬\n       ‫هــي و الهيئــة العامــة للســياحة واآلثــار بإثبــات هــذه الواقعــة و الصحيــح‬\n       ‫أن هنــاك عقــد تشــغيل بــن‪ ...‬وبــن‪ ...‬بخصــوص هــذا الفنــدق و نطلــب‬\n       ‫إدخــال يف القضيــة هكــذا قــال ثــم ســألت املدعــي وكالــة ايضــاح البنــد‬\n       ‫الســابع و العشــرون مــن عقــد االيجــار  املرصــود ســلفا فأجــاب بقولــه إن‬\n       ‫املســتثمر هــو صاحــب الوقــف ويف حالــة بيــع اســتثمار هــذا الفنــدق علــى‬\n       ‫مســتثمر آخــر يطبــق علــى الطــرف الثانــي الــذي هــو املدعــى عليــه مــا‬\n       ‫ينطبــق علــى علــى الطــرف األول الــذي هــو موكلتــي وهــو عــدم جتديــد‬\n       ‫العقــد مــع كمــا هــو األمــر بخصــوص موكلــي هكــذا قــال ثــم جــرى‬\n       ‫منــي اإلطــاع علــى عقــد تشــغيل مبــرم بــن وتتضمــن اآلتــي (عقــد إتفــاق‬\n       ‫بني طرفني بتشــغيل فندق ‪  ...‬لعام ‪1431‬هـ احلمد هلل والصالة والســام‬\n      ‫علــى أشــرف األنبيــاء واملرســلني نبينــا محمــد وعلــى آلــه وصحبه أجمعني ‬\n       ‫وبعــد بعــون اهلل تعالــى مت اإلتفــاق بــن الطرفــن ‪ :‬الطــرف األول ‪ :‬رقــم‬\n       ‫الســجل املدنــي تاريخهــا ‪1409/03/27‬ه ـ الصــادرة مــن جــدة وميثلــه يف‬\n       ‫هــذا العقــد ســعودي اجلنســية رقــم الســجل املدنــي رقــم مبوجــب وكالــة‬\n\n\n‫‪299‬‬\n\f‫رقــم يف ‪1429/5/5‬ه ـ وجلــد رقــم ‪ 2153‬الصــادرة مــن جــدة ويشــار إليــه‬\n‫(املســتأجر)‪ .‬الطــرف الثانــي ‪ ... :‬ســعودي اجلنســية رقــم الســجل املدنــي‬\n‫وعنوانه يف هذا العقد ‪ ...‬شارع ‪  ...‬ج ت ‪ ...‬ص ب ‪ ...‬ويشار إليه (املشغل‬\n‫للفنــدق) املقدمــة ‪ :‬مبــا أن الطــرف األول يعتبــر صاحــب العــن املذكــورة‬\n‫وهــو يف حيازتــه شــرع ًا ملــدة التســع الســنوات املقبلــة حســب العقــد الــذي‬\n‫لديــه مــن ورغــب الطــرف الثانــي يف تشــغيل الفنــدق لكونــه ميلــك اخلبــرة‬\n‫ولــه بــاع طويــل يف تشــغيل الفنــادق ومجــال احلــج والعمــرة علــى أن يكــون‬\n‫لــه قســط ًا مــن املكاســب إن شــاء اهلل لعــام ‪1431‬ه ـ فقــط فقــد إتفقــا‬\n‫علــى مــا يلــي   أو ًال ‪ :‬مدةهــذا العقــد ســنة واحــدة يبــدأ مــن تاريــخ‬\n‫‪1431/01/01‬ه ـ إلــى ‪1431/12/30‬ه ـ ويتجــدد العقــد حســب رغبــة‬\n‫وإتفــاق الطرفــن‪ .‬ثانيـ ًا ‪ :‬يتشــارك الطرفــان بتشــغيل الفنــدق مــن إدارتهــا‬\n‫واإلشــراف عليهــا وعلــى صيانتهــا وعمالهــا وعلــى الطــرف الثانــي إبــرام‬\n‫العقــود مــع شــركات احلــج والعمــرة والبعثــات وكمــا لــه احلق يف إســتالم‬\n‫جميــع مبالــغ اإليــرادات والدفعــات طوالــة فتــرة عقــد التشــغيل املتفــق‬\n‫عليهــا‪ .‬ثالثـ ًا ‪ :‬يتشــارك الطرفــان يف اإلشــراف علــى جميــع األمــور املاليــة‬\n‫التــي تتعلــق بالفنــدق‪ .‬رابعـ ًا ‪ :‬يســتلم الطــرف الثانــي مقابــل تشــغيله هــذه‬\n‫الفتــرة املذكــورة الفائــض مــن اإليــرادات بعــد تســديده مبلــغ وقــدره‬\n‫‪ 1,300,000‬مليــون وثالثمائــة ألــف ريــال للطــرف األول مــن إيــرادات‬\n‫لتشــغيل الفنــدق وذلــك حســب طلبــه لكونــه أهــل للتشــغيل وصاحــب‬\n‫خبــرة يف هــذا املجــال‪ .‬خامسـ ًا ‪ :‬يتحمــل الطــرف الثانــي جميــع مــا يترتــب‬\n‫مــن خســائر يف الفنــدق قــد حتــدث ال قــدر اهلل طوالــة فتــرة العقــد وال‬\n‫يحــق للطــرف الثانــي أن يحمــل الطــرف األول أي خســائر طوالــة فتــرة‬\n‫عقــد التشــغيل‪ .‬سادس ـ ًا ‪ :‬يتحمــل املشــغل الطــرف الثانــي مــن تاريــخ‬\n\n\n                                                                                       ‫‪300‬‬\n\f       ‫إســتالمه العــن املذكــورة مســؤلية إســتخراج التصاريــح والتراخيــص‬\n       ‫الالزمة ودفع كافة الرسوم واإلستيفاءات احلكومية كاإلستخبارات‬\n       ‫واملباحــث اجلنائيــة والغرفــة التجاريــة وجلنــة إســكان احلجــاج وهيئــة‬\n       ‫الســياحة والدفــاع املدنــي وغيرهــا مــن اجلهــات ذات العالقــة مهمــا كان‬\n      ‫نوعهــا واملقــررة علــى العــن‪ .‬ســابع ًا ‪ :‬هــذا العقــد شــخصي للمشــغل املبني ‬\n       ‫إســمه يف هــذا العقــد وال يجــوز التنــازل عنــه للغيــر‪ .‬ثامن ـ ًا ‪ :‬كافــة‬\n       ‫األضــرار التــي تصيــب األرواح أو العقــار أو املمتلــكات اخلاصــة باملشــغل‬\n       ‫أو اجليــران أو غيرهــم مــن أي ســبب كان أو مــن جــراء حريــق قــد ينشــب‬\n       ‫يف العــن مــن أي ســبب كان ال قــدر اهلل يكــون املشــغل وحــده مســئو ًال‬\n       ‫عــن جميــع التعويضــات أو املســؤوليات املدنيــة بالكامــل‪ .‬تاســع ًا إن‬\n       ‫الطــرف األول غيــر مســؤول أمــام أي جهــة كانــت عــن أيــة أضــرار أو‬\n       ‫أخطــار قــد تقــع ال قــدر اهلل يف األرواح واألمــوال بســبب املصاعــد أو‬\n       ‫أســاك الكهربــاء أو ســقوط األمطــار أو إنقطــاع املــاء أو الكهربــاء أو‬\n       ‫ألي ســبب آخــر وعلــى الطــرف الثانــي أن يتخــذ اإلجــراءات الالزمــة‬\n       ‫بنفســه أمــام جهــات اإلختصــاص وإصــاح مــا تعطــل وإعادتــه إلــى وضعه‬\n       ‫الطبيعــي فــور ًا وبــدون أي تأخيــر ودون أي إنتظــار الفصــل يف أي دعــوى‬\n       ‫أو مطالبــة حيــال الغيــر بهــذه األضــرار‪ .‬عاشــر ًا ‪:‬ليــس علــى الطرف األول‬\n       ‫أي مســؤولية مــن أي نــوع كانــت إذا تعرضــت العــن املذكــورة أو‬\n       ‫تعــرض الطــرف الثانــي إلــى عمليــة مــن عمليــات الســرقة أو النصــب أو‬\n       ‫اإلحتيــال وعلــى الطــرف الثانــي أن يتخــذ التدابيــر الالزمــة ملنــع تعرضــه‬\n       ‫ملثــل هــذه العمليــات‪ .‬احلــادي عشــر ‪ :‬يلتــزم الطــرف الثانــي بــأن يجــري‬\n       ‫جميــع أعمــال الصيانــة الداخليــة للعــن املذكــورة طــوال مــدة ســريان‬\n       ‫العقــد ويكــون مســئو ًال مســؤولية كاملــة إذا حــدث أي تلــف أو ضــرر‬\n\n\n‫‪301‬‬\n\f‫للعــن املذكــورة يف اإلصــاح والصيانــة أو عــدم تنفيــذ شــرط اجلــودة‬\n‫والنوعيــة يف أعمــال الصيانــة الالزمــة‪ .‬الثانــي عشــر ‪ :‬إلتــزم الطــرف‬\n‫الثانــي بتســليم العــن املذكــورة محــل هــذا العقــد للطــرف األول بحالتــه‬\n‫التــي كان عليهــا عنــد التعاقــد صاحل ـ ًا للســكن بكافــة معداتــه‬\n‫وأجهزتــه ومفروشــاته ومحتوياتــه الــواردة مبحضــر التســليم املرفــق بهــذا‬\n‫العقــد مــع مراعــاة نســبة اإلســتهالك املتعــارف عليهــا بخصــوص األثــاث‬\n‫واملفروشــات والتجهيــزات ومســتوفى ملــا يلــزم مــن عمــل إصالحــات‬\n‫وصيانــة للســباكة والكهربــاء والنجــارة والدهــان واملصاعــد وخالفــه‬\n‫ممــا جــرت بــه العــادة يف مثيالتــه علــى أن يقــوم الطــرف الثانــي بتمكــن‬\n‫الطــرف األول مــن اإلطــاع علــى جميــع اإلصالحــات ويكــون تســليم‬\n‫بعــد إنتهــاء مــدة التعاقــد مبحضــر إســتالم يثبــت فيــه حالته عند التســليم‬\n‫ويف حــال ظهــور نقــص أو تلفيــات يف املبنــى أو جتهيزاتــه يلتــزم الطــرف‬\n‫الثانــي بإصالحهــا وإعادتهــا كمــا كانــت علــى حســابه اخلاص‪.‬الثالــث‬\n‫عشــر ‪ :‬يعتبــر عنــوان كل طــرف املوضــح قريــن إســمه يف هــذا العقــد‬\n‫موطنـ ًا مختــار ًا فيمــا يتعلــق بتنفيــذ املراســات التــي تخــص هــذا العقــد‬\n‫مــا لــم يخطــر أحــد الطرفــن الطــرف اآلخــر كتابي ـ ًا بتغييــره‪ .‬الرابــع‬\n‫عشــر ‪ :‬إتفــق الطرفــان علــى أنــه لــو حصــل هــدم للعــن املذكــورة مــن‬\n‫قبــل احلكومــة فــإن الطــرف األول غيــر مســئو ًال عــن ذلــك وحتســب املبلغ‬\n‫املتفــق عليــه حتــى تاريــخ الهــدد مبوجــب محضــر رســمي بذلــك‪ .‬اخلامــس‬\n‫عشــر ‪ :‬كل تغييــر يف شــروط هــذا العقــد ال يعتــد بهــا إال إذا كانــت‬\n‫بتوقيــع الطــرف األول ومبوافقتــه اخلطيــة‪ .‬الســادس عشــر ‪ :‬مــن حــق‬\n‫الطــرف األول إســتالم املبنــى وحيازتــه بتاريــخ ‪1432/1/1‬ه ـ دون‬\n‫الرجــوع إلــى الطــرف الثانــي ودون موافقتــه ويف حالــة تأخــر احلجــاج‬\n\n\n                                                                                    ‫‪302‬‬\n\f      ‫لســبب طــارئ يعطــى الطــرف الثانــي مهلــة إلكمــال ترحيــل احلجــاج‬\n      ‫مبتابعــة وحضــور الطــرف األول وإســتالمه املبنــى مــع إلتــزام الطــرف‬\n      ‫الثانــي بتحمــل فواتيــر امليــاه والكهربــاء واخلدمــات طيلــة هــذه املهلــة‬\n      ‫والتــي ال تتعــدى عشــرة أيــام‪ .‬الســابع عشــر ‪ :‬وافــق الطــرف الثانــي علــى‬\n      ‫بنــود هــذا العقــد بطوعــه وإختيــاره وإلتــزم بالتقيــد مبوجبــه فــإن أخــل‬\n      ‫الطــرف الثانــي بشــيء مــن ذلــك فإنــه يحــق للطــرف األول إخــاء العــن‬\n      ‫بــدون قيــد أو شــرط ويصبــح العقــد الغيـ ًا وللطــرف األول حــق املطالبــة‬\n      ‫فيمــا إســتخدمت فيــه العــن املذكــور حتــى تاريــخ إلغــاء العقــد‪ .‬الثامــن‬\n      ‫عشــر ‪ :‬املطعــم مــن خصوصيــات الطــرف األول وعلــى الطــرف الثانــي ‪...‬‬\n      ‫‪ % 10‬مــن قيمــة فواتيــر امليــاه والكهربــاء فقــط‪ .‬التاســع عشــر ‪ :‬يف حالــة‬\n      ‫بيــع اإلســتثمار ال قــدر اهلل مــن املســتثمر وإثباتــه شــرع ًا ينطبــق علــى‬\n      ‫الطــرف الثانــي مــا ينطبــق علــى الطــرف األول يف مــدة ســريان هــذا‬\n      ‫العقــد‪ .‬العشــرون ‪ :‬علــى الطــرف الثانــي عمــل ســيراميك يف الغــرف‬\n      ‫وجتديــد البويــة وعمــل جميــع مــا يلــزم مــن صيانــة شــاملة ويف حالــة أن‬\n      ‫الطــرف الثانــي غيــر الســرير القــدمي والثالجــات أو أي شــيء متحــرك‬\n      ‫قــدمي علــى الطــرف الثانــي إبقاؤهــا وال يحــق لــه أخذهــا ألنهــا حلــت محــل‬\n      ‫القــدمي وال يحــق لــه املطالبــة بــأي تعويــض يف أي حــال مــن األحــوال‪.‬‬\n      ‫احلــادي والعشــرون ‪ :‬هــذا العقــد ملــزم للطرفــن ولورثتهمــا مــن بعدهــم ال‬\n      ‫يجــوز فســخه وال إلغــاؤه إال بعقــد خطــي جديــد موقــع مــن الطرفــن‬\n      ‫وبغيــر ذلــك ال يلتفــت إلــى أي تصــرف مــن أي مــن الطرفــن مهمــا كانــت‬\n      ‫األســباب إال مــا نصــت عليــه بنــود هــذا العقــد‪ .‬الثانــي والعشــرون ‪ :‬يلتــزم‬\n      ‫الطــرف الثانــي بدفــع املبلــغ املتفــق عليــه وهــو ‪ 1.300.000‬مليــون‬\n      ‫وثالثمائــة ألــف ريــال علــى دفعــات حســب مــا إتفــق عليــه الطرفــان علــى‬\n\n\n‫‪303‬‬\n\f‫النحــو التالــي ‪ :‬يدفــع مبلــغ وقــدره ‪ 650.000‬ســتمائة ألــف وخمســون‬\n‫ألــف ريــال فقــط عنــد توقيــع هــذا العقــد‪ .‬يدفــع مبلــغ وقــدره ‪350.000‬‬\n‫ثالثمائــة ألــف وخمســون ألــف ريــال فقــط بتاريــخ ‪1431/05/15‬ه ـ‬\n‫مبوجــب شــيك يدفــع مبلــغ وقــدره ‪ 300.000‬ثالثمائــة ألــف ريــال فقــط‬\n‫بتاريــخ ‪1431/09/10‬ه ـ مبوجــب شــيك الثالــث والعشــرون ‪ :‬ويف حالــة‬\n‫تأخــره عــن الدفعــات أكثــر مــن أســبوع أقصــاه يحــق للطــرف األول‬\n‫إبــرام العقــود وإســتالم املبالــغ مــع البعثــات والشــركات بــدون أي قيــد‬\n‫أو شــرط أو الرجــوع إليــه وكمــا يحــق لــه فســخ هــذا العقــد يف حينــه‬\n‫وإســتالم جميــع األمــور التــي تعلــق بالفنــدق وكمــا يحــق لــه املطالبــة‬\n‫بجميــع املبالــغ املســتحقة‪ .‬الرابــع والعشــرون ‪ :‬يف حالــة وجــود أي عقــد‬\n‫بــن الطرفــن قبــل ســريان هــذا العقــد مــن تاريــخ ‪1431/1/1‬ه ـ فهــو‬\n‫يعتبــر الغي ـ ًا بإتفــاق الطرفــن ويعتبــر هــذا العقــد هــو العقــد اجلديــد‬\n‫بشــروط جديــدة وبتاريــخ جديــد‪ .‬وقــع الطرفــان هــذا العقــد وهمــا‬\n‫بكامــل األهليــة املعتبــرة شــرع ًا والرضــى الكامــل علــى هــاذا اإلتفــاق‬\n‫والتزمــا بكامــل بنــوده وأذنــا ملــن يشــهد واهلل خيــر الشــاهدين‪ .‬وكتــب‬\n‫هــذا العقــد نســختني  أصليتــن بيــد كل طــرف نســخة وحــرر يف‬\n‫‪1431/11/29‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم وبــاهلل التوفيــق) وبتصفــح أوراق املعاملــة وجــدت ضمــن طياتهــا‬\n‫عقــدا مبرمــا بــن ‪ ...‬و‪....‬ويتضمــن اآلتــي (احلمــد هلل وحــده والصــاة‬\n‫والســام علــى مــن ال نبــي بعــده وعلــى آلــه وصحبــه أجمعــن وبعــد‬\n‫الطــرف األول ســعودي اجلنســية رقــم احلفيظــة رقــم الســجل املدنــي‬\n‫تاريخهــا ‪1409/03/27‬ه ـ مصدرهــا جــدة وميثلــه الوكيــل الشــرعي‬\n‫رقــم احلفيظــة تاريخهــا ‪1398/01/07‬ه ـ مصدرهــا مكــة املكرمــة‬\n\n\n                                                                                   ‫‪304‬‬\n\f      ‫رقــم الوكالــة ‪ 8292‬تاريخهــا ‪1427/04/10‬ه ـ الطــرف الثاني ســعودية‬\n      ‫اجلنســية رقــم الســجل املدنــي تاريخهــا ‪1401/12/20‬ه ـ الصــادرة مــن‬\n      ‫الريــاض وميثلهــا الوكيــل الشــرعي رقــم الوكالــة ‪ 1/18‬تاريخهــا‬\n      ‫‪1427/11/08‬ه ـ رقــم احلفيظــة تاريخهــا ‪1408/11/04‬ه ـ مصدرهــا‬\n      ‫ثــادق علــى إيجــار املســمى فنــدق  ‪  ...‬مبرافقــه ومحالتــه التجاريــة ملــك‬\n      ‫وقــف ‪ ...‬بجــوار فنــدق ‪ ...‬شــارع ‪  ...‬مببلــغ وقــدره مليــون ريــال الســنة‬\n      ‫األولــى مــن تاريــخ ‪1428/01/01‬ه ـ إلــى ‪1429/01/01‬ه ـ وثــاث‬\n      ‫ســنوات التاليــة يكــون اإليجــار مليــون وثالثــون ألــف ريــال ســنويا مــع‬\n      ‫املطعــم ومحالتــه وبعــد هــذه الفتــرة املذكــورة الباقيــة مــن العقــد‬\n      ‫ســيكون اإليجــار مليــون وخمســون ألــف ريــال إلــى نهايــة عقــد املالــك‬\n      ‫املؤجــر املســتثمر الــذي هــو أربعــة عشــرة ســنة واتفــق الطرفــان علــى‬\n      ‫الشــروط التاليــة ‪ -1 :‬مــدة اإليجــار عــدا الســنة األولــى مــن بدايــة تاريــخ‬\n      ‫‪/1‬محــرم بقيــة الســنوات إلــى نهايــة عقــد املؤجــر املســتثمر أربعــة عشــرة‬\n      ‫ســنة ‪ -2‬الدفعــة األولــى عنــد توقيــع العقــد مبلــغ خمســمائة ألــف ريــال‬\n      ‫الدفعــة الثانيــة بتاريــخ ‪1428/07/30‬ه ـ مبلــغ مائتــن ألــف ريــال الدفعــة‬\n      ‫الثالثــة بتاريــخ ‪1428/09/25‬ه ـ مبلــغ ثالثمائــة مائــة ألــف ريــال ويكــون‬\n      ‫الدفعــة األخيــرة يف الســنوات القابلــة حســب املبلــغ املتبقــي مــن اإليجــار‬\n      ‫كمــا أنــه ســيكون الدفعــة األولــى مــن الســنة التاليــة بتاريــخ‬\n      ‫‪1429/03/30‬ه ـ ‪ -3‬يتــم تســليم العمــارة ومحتوياتــه رســميا وبتوقيــع‬\n      ‫الطرفــان كمــا أنــه يف حالــة الرجــوع قــدر اهلل يتــم مبثلــه ‪ -4‬يف حالــة‬\n      ‫تطويــر املنطقــة وإلــزام املؤجــر الهــدم قــدر اهلل للموقــع مــن اجلهــات‬\n      ‫احلكوميــة يحــق للطــرف األول فســخ العقــد ‪ -5‬يف حالــة تأخيــر اإليجــار‬\n      ‫عــن التاريــخ املذكــور للدفعــة أقصــى مــدة شــهر يحــق للطــرف األول‬\n\n\n‫‪305‬‬\n\f‫فســخ العقــد ومطالبتــه باألمــور املاليــة ويف حالــة االنضبــاط بالدفعــات‬\n‫يتجــدد تلقائيــا علــى مــا تفــق عليــه الطرفــان عنــد توقيــع العقــد بتاريخــه‬\n‫‪ -6‬علــى الطــرف األول إعطــاء جميــع األوراق الالزمــة للتصاريــح‬\n‫ومراجعــة الدوائــر احلكوميــة مــن صكــوك وتصاريــح بنــاء وتصريــح‬\n‫احلــج الســابق األصــل مــع تنــازل املســتثمر الســابق ووكالــة إن لــزم األمــر‬\n‫إلخــراج جميــع التصاريــح الالزمــة مــن جلنــة احلــج والتجــارة وعمــل العقــود‬\n‫ومراجعــة جميــع الدوائــر احلكوميــة ‪ -7‬يف حالــة البيــع قــدر اهلل مــن‬\n‫املالــك املؤجــر املســتثمر (الطــرف‪ 6‬األول) يجــب عليــه إشــعار الطــرف‬\n‫الثانــي قبــل شــهرين مــن نهايــة الســنة ويلتــزم الطــرف األول بالعقــد إلــى‬\n‫نهايــة الســنة ‪ -8‬ال يعتبــر اإليجــار مســدد إال بعــد حصــول الطــرف الثانــي‬\n‫علــى إيصــال قبــض مــن الطــرف األول ‪ -9‬يلتــزم الطــرف الثانــي بجميــع‬\n‫الرســوم وتســديد فواتيــر جميــع اخلدمــات املتعلقــة بعــن العقــار حتــى‬\n‫نهايــة العقــد ويقــدم يف نهايــة العقــد فواتيــر اخلدمــات للطــرف األول‬\n‫مســددة وقــع الطرفــان وهــم بكامــل األهليــة املعتبــرة شــرعا والرضــى‬\n‫الكامــل علــى هــذا االتفــاق والتزمــا بكامــل بنــوده وأذنــا ملــن يشــهد‬\n‫واهلل خيــر الشــاهدين نســأل اهلل ســبحانه وتعالــى أن يبــارك يف هــذا‬\n‫العقــد ويف أهلهــا القائمــن وأن يوفــق اجلميــع ملــا يحبــه ويرضــاه إنــه ولــي‬\n‫ذلــك والقــادر عليــه) ثــم ســألت املدعــى عليــه وكالــة هــل تطعــن يف‬\n‫العقــد املبــرم بــن املدعيــة وبــن‪ .....‬بشــيء فقــال إنــي ال أعلــم عنــه شــيئا‬\n‫ثــم ســألت املدعــي وكالــة هــل جــددت موكلتــه مــع املدعــى عليــه العقــد‬\n‫املبــرم بينهمــا فقــال إنــا كنــا جنــدد العقــد مــع املدعــى عليــه وذلــك ملــدة‬\n‫ثــاث ســنوات ولكــن تفاجأنــا بأنــه أبــرم عقــدا آخــر مــع شــخص يدعــى‬\n‫وبعــرض ذلــك علــى املدعــى عليــه قــال إن موكلــي عقــده كمــا ذكــرت‬\n\n\n                                                                                         ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":277,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a0740b89a16892f9b77e055c7edcda7bd2d8bb1722de5d9d0f300cb342ca386b","normalized_text_hash":"fb4d831e9d624563c534889dfc85c0c3a8f45d10abbb79e840527cdbf401f964","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p277-3449949"},{"id":"61171b62-2a2d-5f8a-a707-86192e14b818","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبه باسترجاع حيازة عن مؤجره -الدفع بشراء العن -ثبوت العلم باإلجارة قبل الشراء -احلكم بإلزام املالك بإعادة العن للمستأجر حتى نهاية عقده .","document_number":"34165513","case_number":"3459238","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/18","year":"1434","subject":"إجارة -مطالبه باسترجاع حيازة عن مؤجره -الدفع بشراء العن -ثبوت العلم باإلجارة قبل الشراء -احلكم بإلزام املالك بإعادة العن للمستأجر حتى نهاية عقده .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/18 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34165513 :‬‬\n                    ‫َر ْق ُم الدعوى‪3459238 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34246620‬تاريخه‪1434/6/20 :‬هـ‬\n\n\n\n‫إجــارة ‪ -‬مطالبــه باســترجاع حيــازة عــن مؤجــره ‪ -‬الدفــع بشــراء العــن‬\n‫‪ -‬ثبــوت العلــم باإلجــارة قبــل الشــراء ‪ -‬احلكــم بإلــزام املالــك بإعــادة‬\n                                    ‫العــن للمســتأجر حتــى نهايــة عقــده ‪.‬‬\n\n\n\n\n‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بأنــه اســتأجر اســتراحة ملــدة‬\n‫خمــس ســنوات وخــال املــدة اســتدعاه املدعــى عليــه وأخبــره انــه اشــترى‬\n‫االســتراحة مــن املالــك (املؤجــر) وطلــب تعديــل العقــد فامتنــع فطلــب منــه‬\n‫مفاتيحهــا ليراهــا راغبــا بشــرائها فناولــه مفاتيحها ولــم يعدها له وطرده‬\n‫مــن االســتراحة وطلــب إلزامــه بإعــادة االســتراحة لــه حــاال ‪ -‬أجــاب‬\n‫املدعــى عليــه بأنــه اشــترى االســتراحة مــن املالــك الســابق وأنــه أخبــره‬\n‫بأنهــا مســتأجرة ودفــع بــأال شــأن لــه باملســتأجر وطلــب صــرف النظر عن‬\n‫دعــواه ‪ -‬طلبــت الدائــرة إحضــار املالــك فحضــر مــع املدعــي ولــم يحضــر‬\n‫املدعــى عليــه وقــرر املالــك بأنــه أخبــر املدعــى عليــه بأنهــا مؤجــرة خمــس‬\n\n                                                                                      ‫‪310‬‬\n\f      ‫ســنوات واتفــق معــه علــى أن تكــون األجــرة لــه ‪ -‬ملــا تقــدم والعتــراف‬\n      ‫املدعــى عليــه بــأن البائــع أخبــره بــأن االســتراحة مؤجــرة خمــس ســنوات‬\n      ‫واســتلم إيجــار ســتة أشــهر لــذا فهــو علــى علــم وبصيــرة بعقــد اإلجــارة‬\n      ‫لــذا فقــد حكمــت الدائــرة علــى املدعــى عليــه بــأن يســلم االســتراحة‬\n      ‫ومفاتيحهــا للمدعــي وعــدم معارضتــه ومنازعتــه يف املــدة املتفــق عليهــا‬\n      ‫يف العقــد وهــي خمــس ســنوات بدايــة مــن ‪1433/3/1‬ه ـ حتــى نهايتهــا‬\n      ‫حكم ـ ًا مصحوبــا بالنفــاذ املعجــل واعتبــرت احلكــم عليــه حضوريــا‬\n      ‫وأمــرت بتنظيــم صــك وإرســال صــورة منــه للمدعــى عليــه لالعتــراض‬\n      ‫عليــه مــن عدمــه ‪ -‬قــدم املدعــى عليــه الئحــة اعتراضيــة ‪-‬صــدق احلكــم‬\n                                                        ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪   ........................‬القاضــي يف احملكمــة العامــة بينبــع وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة مســاعد رئيــس احملكمــة العامــة‬\n      ‫بينبــع برقــم ‪ 3459238‬وتاريــخ ‪ 1434/02/05‬هــ  املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 34259851‬وتاريــخ ‪ 1434/02/02‬هــ   ففــي يــوم   األربعــاء‬\n      ‫املوافــق‪ 1434/02/20‬ه ـ افتتحــت اجللســة الســاعة ‪  08 : 30‬وفيهــا‬\n      ‫حضــر  ‪  ........................‬ســعودي  اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ .................‬ولــم يحضــر املدعــى عليــه ‪ .................‬وقــد ذكــر محضــر‬\n      ‫اخلصــوم بأنــه مت االتصــال علــى جوالــه فــردت امــرأة وذكــرت بأنــه‬\n      ‫غيــر موجــود وســوف تبلغــه عنــد عودتــه إلــى املنــزل مبراجعــة احملكمــة‬\n      ‫لــذا رفعــت اجللســة وحــدد لهــم موعــد يف يــوم الســبت ‪1434/02/30‬ه ـ‬\n‫‪311‬‬\n\f‫الســاعة احلاديــه عشــر  ففــي يــوم الســبت املوافــق ‪ 1434/02/30‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪  11.30‬وفيهــا حضــر املدعــي ‪......................‬‬\n‫وحضــر حلضــوره املدعــى عليــه ‪ ...................‬ســعودي اجلنســية مبوجــب‬\n‫ا ادعــي علــى‬     ‫الســجل املدنــي رقــم ‪ ......................‬ثــم ادعــى املدعــي قائـ ً‬\n‫احلاضــر معــي باملجلــس الشــرعي ‪ ...................‬الــذي طردنــي وأســتولى‬\n‫علــى االســتراحة التــي ســبق وان اســتأجرتها مــن ‪ ..............‬والواقعــة يف‬\n‫‪ ...‬هــ‪ 4‬يف طريــق ‪ ...‬وقــد ســبق وأن اســتأجرتها مــن مالكهــا ‪.............‬‬\n‫مببلــغ وقــدرة ثمانيــة وثالثــون الــف ريــال وذلــك ملــدة خمــس ســنوات بدايــة‬\n‫مــن ‪1433/3/1‬ه ـ وقــد دفعــت لــه تســعة عشــر ألــف ريــال ل‪..............‬‬\n‫وأثثــت االســتراحة مبــا يقــارب الســتني ألــف ريــال وأنــا أؤجرهــا باليــوم‬\n‫علــى النــاس ثــم حضــر لــي ‪ .........‬وقــال لــي أنــي بعــت االســتراحة ل‪.........‬‬\n‫واعــط الســتة األشــهر الباقيــة ل‪ ..........‬وأســتمر معــه املــدة الباقيــة ثــم‬\n‫اتصــل بــي املدعــى عليــه عــن طريــق الهاتــف وقــال  أحضــر إلــى املنــزل‬\n‫ومعــك العقــد األصــل وحضــرت إليــه ومعــي صــورة منــه وقــال نريــد ان‬\n‫نغيــر العقــد وقلــت أذا تريــد تغييــر العقــد فــا بد ان يكــون لدى مكتب‬\n‫العقــار الــذي اســتأجرت منــه ســابق ًا ويف يــوم ‪1434/1/14‬ه ـ أتصــل بــي‬\n‫املدعــى عليــه وقــال أريــد املفاتيــح لــدي زبــون أريــد ان ابيــع االســتراحة‬\n‫ا ســلمته املفاتيــح وبعدهــا قــال أذهــب عنــي االســتراحة اســتراحتي‬               ‫وفعـ ً‬\n‫وأنــا لــم اؤجــرك شــيئ ًا وقــد اشــتريتها مبالــي وليــس لــدي لــك أي شــيء‬\n‫عنــد ذلــك تقدمــت إلــى احملكمــة وبعــرض ذلــك علــى املدعــى عليــه‬\n‫ا اشــتريت تلــك االســتراحة وقــال لــي ‪ ...‬تراهــا مؤجــرة‬            ‫أجــاب قائـاً  فعـ ً‬\n‫ملــدة خمــس ســنوات علــى ‪ ............‬وقلــت لــه انــا ال أريــد ان أجرهــا وقــال‬\n‫لــي بقــي تســعة عشــر ألــف مــن الســنة االولــى قلــت لــه ال يهمنــي التســعة‬\n\n\n                                                                                               ‫‪312‬‬\n\f      ‫ا‬‫عشــر ألــف ويهمنــي اســتالم االســتراحة وبعــد تســعة اشــهر تقريبـ ًا فعـ ً‬\n      ‫اخــذت املفاتيــح واالســتراحة اســتراحتي ودافــع فيهــا فلوســي وطلبــت‬\n      ‫مــن املدعــي إحضــار عقــد اإليجــار وكذلــك البائــع وطلبــت مــن املدعــى‬\n      ‫عليــه إحضــار كذلــك أصــل صكــه وأســتعد بذلــك وحــدد لهــم جلســة‬\n                          ‫وذلــك يف يــوم الثالثــاء ‪1434/3/17‬ه ـ الســاعة العاشــرة ‪.‬‬\n      ‫ففــي يــوم  الثالثــاء املوافــق‪ 1434/03/17‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10.00‬وفيهــا حضــر املدعــي ‪ ................‬واحضــر البائــع ‪.......................‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل رقــم ‪ ...................‬ولــم يحضــر‬\n      ‫حلضــوره املدعــى عليــه ‪........................‬وبعــرض دعــوى املدعــي علــى‬\n      ‫ا نعــم ســبق وأن اجــرت تلــك االســتراحة العائــدة‬             ‫البائــع ‪ ...‬أجــاب قائ ـ ً‬\n      ‫لــي والواقعــة يف ه ـ ‪ 4‬مخطــط ‪...‬علــى املدعــي بدايــة مــن ‪1433/3/1‬ه ـ‬\n      ‫ملــدة خمــس ســنوات ثــم بعتهــا علــى املدعــي عليــه ‪ ..................‬واخبرتــه‬\n      ‫بــان االســتراحة مؤجــرة ملــدة خمــس ســنوات واعطيتــه صــورة مــن عقــد‬\n      ‫اإليجــار وقــال ليــس هنــاك لــدي مشــكلة وســوف يبقــى املؤجــر يف تلــك‬\n      ‫االســتراحة ولــن اطــرده منهــا حتــى يســتويف مدة إجارته وبقي ســتة اشــهر‬\n      ‫ومت االتفــاق بينــي وبــن املشــتري بــان يســتلم إيجارهــا مــن املســتأجر‬\n      ‫وقــدر ذلــك تســعة عشــر الــف وفعــا أســتلمها فهــو علــى علــم وبصيــرة‬\n      ‫باملســتأجر وباملــدة ثــم ســالته الديــك صــورة مــن صــك االســتراحة فقــال‬\n      ‫ال توجــد لــدي صــورة مــن ذلــك الصــك وقــد أفرغــت صكهــا للمشــتري‬\n      ‫ثــم طلبــت مــن املدعــي كذلــك إبــراز عقــد اإليجــار فأبــرز لنــا العقــد‬\n      ‫املــؤرخ يف ‪1433/2/16‬ه ـ الــذي جــاء فيهــا الطــرف االول ‪................‬‬\n      ‫والطــرف الثانــي ‪ ..................‬ونــوع العقــار اســتراحة املوقــع ه ـ ‪ 4‬القيمــة‬\n      ‫اإليجاريــة ثمانيــة وثالثــون ألــف ريــال وبدايــة العقــد يف ‪1433/3/1‬ه ـ‬\n\n\n‫‪313‬‬\n\f  ‫واملــدة املتفــق عليهــا خمــس ســنوات وهنــاك عــدة شــروط مــن احملافظــة‬\n  ‫علــى العــن وعــدم مضايقــة اجليــران ووقــع الطــرف االول علــى اليمــن‬\n  ‫والطــرف الثانــي علــى اليســار وبنــاء علــى دعــوى املدعــي وجــواب املدعــى‬\n  ‫عليــه واعتــراف املدعــى عليــه بانــه اخبــره ‪ ...‬بــان االســتراحة مؤجــرة ملــدة‬\n  ‫خمــس ســنوات وقــد اســتلم إيجــار ســتة اشــهر فهــو علــى علــم وبصيــرة‬\n  ‫باإلجــارة لــذى حكمــت علــى املدعــى عليــه ‪ ..........‬بــان يســلم االســتراحة‬\n  ‫ومفاتيحهــا للمدعــي وعــدم معارضتــه ومنازعتــه يف تلــك املــدة املتفــق‬\n  ‫عليهــا يف العقــد وهــي خمــس ســنوات بدايــة مــن ‪1433/3/1‬ه ـ حتــى‬\n  ‫ا واعتبــرت املدعــى عليــه مبلغـ ًا لذاتــه فهــو حكــم‬   ‫نهايتهــا حكمـ ًا معجـ ً‬\n  ‫حضــوري وامــرت بتنظيــم صــك وإرســال صــورة منــه للمدعــى عليــه‬\n  ‫لالعتــراض عليــه مــن عدمــه ومــدة االعتــراض ثالثــون يومــا أمــا املــدة‬\n  ‫التــي بقيــت يف يــد املدعــى عليــه فللمدعــي املطالبــة بهــا بعــد اســتالمه‬\n  ‫تلــك االســتراحة أمــا املدعــي فقــال إننــي قانــع باحلكــم وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‬\n                                                                  ‫‪ 1434/03/17‬ه ـ‬\n  ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي أنــا‬\n  ‫‪   ......................‬القاضــي يف احملكمــة العامــة بينبــع   وبنــاء علــى املعاملة‬\n  ‫احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة العامــة بينبــع املســاعد برقــم‬\n  ‫‪ 3459238‬وتاريخ ‪ 1434/02/05‬هـ  املقيدة باحملكمة برقم ‪34259851‬‬\n  ‫وتاريــخ ‪ 1434/02/02‬هــ  ففــي يــوم  اإلثنــن املوافــق‪1434/07/17‬‬\n  ‫ه ـ افتتحــت اجللســة   وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n  ‫مبكــة املكرمــة برقــم ‪ 341426279‬يف ‪1434/16/24‬ه ـ والصــادر‬\n  ‫فيهــا القــرار رقــم ‪ 34246620‬يف ‪1434/06/20‬ه ـ الصــادر مــن الدائــرة‬\n\n\n                                                                                             ‫‪314‬‬\n\f      ‫احلقوقيــة الســابعة ومفــاده فقــد جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫الســابعة مبحكمــة االســتئناف يف منطقــة مكــة املكرمــة االطــاع‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامة بينبع املســاعد‬\n      ‫برقــم ‪ 341426279‬وتاريــخ ‪1434/06/13‬ه ـ املرفــق بها الصك الصادر‬\n      ‫مــن فضيلــة الشــيخ ‪ .......................‬القاضــي باحملكمــة العامــة بينبــع‬\n      ‫املســجل برقــم ‪ 34165513‬وتاريــخ ‪1434/03/18‬ه ـ املتضمــن دعــوى‬\n      ‫‪ .................‬ضــد ‪ ...................‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم قاضــي اســتئناف ‪.................‬‬\n      ‫قاضــي اســتئناف ‪ ..............‬رئيــس الدائــرة ‪   .....................‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                    ‫يف  ‪ 1434/07/17‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪ 341426279‬وتاريــخ‬\n      ‫‪1434/06/13‬هـ املرفق بها الصك الصادر من فضيلة الشيخ ‪...............‬‬\n      ‫القاضــي باحملكمــة العامــة بينبــع املســجل برقــم ‪ 34165513‬وتاريــخ‬\n      ‫‪1434/03/18‬ه ـ املتضمــن دعــوى ‪ .......................‬ضــد ‪،...................‬‬\n      ‫وبدراسة الصك وص ــورة ضبط ــه والئحته اإلعتراضية تق ــررت املوافق ــة‬\n      ‫عل ــى احلكــم‪  .‬واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه‬\n                                                                            ‫وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":310,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4858dcc08d0275f973582b518f8e2a2b9a6762972ea767686b0a98c5c16a48ef","normalized_text_hash":"01669b4f2dd23f3dd02704ade47ca7a12baca5e84229847fee0a122c6f9d75ac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p310-34165513"},{"id":"179bd7e5-6bf7-556a-9521-7bdb07e77b51","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مطالبة بأجرة محل -الدفع باشتراط التمكن من مزاولة نشاط معن فيه -عدم ثبوت الشرط -احلكم بإلزام املدعى بدفع األجرة املستحقة.","document_number":"34204225","case_number":"3474920","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"عقد -إجارة -مطالبة بأجرة محل -الدفع باشتراط التمكن من مزاولة نشاط معن فيه -عدم ثبوت الشرط -احلكم بإلزام املدعى بدفع األجرة املستحقة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/4 :‬هـ  ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34204225 :‬‬\n                           ‫َر ْق ُم الدعوى‪3474920 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34272313‬تاريخه‪1434/7/18 :‬هـ‬\n\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬مطالبــة بأجــرة محــل ‪ -‬الدفــع باشــتراط التمكــن مــن‬\n      ‫مزاولــة نشــاط معــن فيــه ‪ -‬عــدم ثبــوت الشــرط ‪ -‬احلكــم بإلــزام املدعــى‬\n                                                         ‫بدفــع األجــرة املســتحقة‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                               ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بأنــه اســتأجر منــه أربعــة‬\n      ‫دكاكــن بأجــرة ومــدة محــددة وقــد ســلم بعــض األجــرة لــذا يطلــب‬\n      ‫إلزامــه بدفــع الباقــي ‪ -‬أقــر املدعــى عليــه باألجــرة إال أنــه دفــع بأنــه‬\n      ‫اســتأجرها حســب االتفــاق مــع املدعــي لتكــون صيدليــة وتقــدم بطلــب‬\n      ‫للبلديــة والشــؤون الصحيــة فــردوا الطلــب لعــدم وجــود مواقــف ســيارات‬\n      ‫لهــا لــذا فقــد بعــث خطابــا للمؤجــر بطلــب اإلقالــة وإعــادة املبلــغ املســلم‬\n      ‫لعــدم التحقــق مــن الغــرض ‪ -‬بعرضــه علــى املدعــي قــرر بــأن املســتأجر‬\n      ‫لــم يشــرط عليــه ذلــك بــل أخبــره بأنــه يرغــب يف فتــح مكتــب مصاعــد‬\n      ‫ومســتودع ‪ -‬جــرى التحقــق مــن ملكيــة املدعــي للعقــار باالطــاع علــى‬\n\n‫‪323‬‬\n\f‫صكــه ورصــد مضمونــه ‪ -‬جــرى االطــاع علــى وثيقــة العقــد فلــم يظهــر‬\n‫وجــود شــرط علــى املدعــي بتمكــن املدعــى عليــه ممــا دفــع بــه ‪ -‬جــرى‬\n‫ســؤال املدعــى عليــه ألديــه بينــة علــى اشــتراطه فنفــى ‪ -‬بنــاء علــى دعــوى‬\n‫املدعــي وجــواب املدعــى عليــه وعلــى وثيقــة عقــد اإليجــار حيــث لــم‬\n‫يظهــر فيهــا اشــتراط املدعــى عليــه متكنــه مــن مزاولــة نشــاطه التجــاري‬\n‫يف مجــال الصيدلــة بــل دفــع مــن األجــرة دفعتــن وهــذا دليــل علــى رضــاه‬\n‫يؤيــده أن مــدة العقــد ثــاث ســنوات أوشــكت علــى االنتهــاء ولــم يــورد‬\n‫هــذا الدفــع إال مــع قــرب انتهــاء املــدة لــذا فقــد قــررت الدائــرة احلكــم‬\n‫علــى املدعــى عليــه بــأن يدفــع للمدعــي باقــي األجــرة املســتحقة ‪ -‬بعــرض‬\n‫احلكــم علــى املدعــى عليــه لــم يقنــع وجــرى تســليمه صــورة الصــك وأفهم‬\n                   ‫بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n  ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة‬\n  ‫بينبــع   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبــع املســاعد برقــم ‪ 3474920‬وتاريــخ ‪ 1434/02/16‬هــ  ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34377114‬وتاريــخ ‪ 1434/02/16‬هــ  ‬\n  ‫ففــي يــوم  الســبت املوافــق‪ 1434/02/30‬ه ـ افتتحــت اجللســة الســاعة‬\n  ‫‪08 : 00‬وفيهــا حضــر املدعــي ‪ ................‬ســعودي  اجلنســية مبوجــب‬\n  ‫الســجل املدنــي رقــم ………‪  .‬ولــم يحضــر املدعــى عليــه وقــد تبلــغ‬\n  ‫عــن طريــق موظفــه بالشــركة ‪ ................‬ولكــن لــم يحضــر واعطــي‬\n‫موعــد جلســة وذلــك يف يــوم  األحــد ‪1434/3/29‬ه ـ الســاعة العاشــرة  ‬\n  ‫والنصــف صباحــا ففــي يــوم  األحــد املوافــق ‪1434/03/29‬ه ـ افتتحــت‬\n                                                                                         ‫‪324‬‬\n\f      ‫اجللســة الســاعة ‪ 10.30‬وفيهــا حضــر املدعــي ‪ ..................‬وحضــر‬\n      ‫وكيــل الشــركة ‪ ....................‬ســعودي اجلنســية مبوجــب الســجل رقــم‬\n      ‫…………………‪ ..‬مبوجــب وكالتــه الصــادرة مــن كتابــة عــدل ينبــع‬\n      ‫برقــم ‪  34373545‬يف ‪1434/3/25‬هــ  والتــي تخولــه عــن موكلــة يف‬\n      ‫املرافعــة واملدافعــة وســماع الدعــاوي والــرد عليهــا واإلقــرار والصلــح‬\n      ‫والتنــازل وطلــب اليمــن وقبــول األحــكام واالعتــراض عليهــا   ثــم‬\n      ‫ا ادعــي الغائــب عــن املجلــس الشــرعي ‪...................‬‬  ‫ادعــى املدعــي قائ ـ ً‬\n      ‫وذلــك مبواجهــة وكيلــة ‪ ..................‬الــذي ســبق أن أجــرت عليــه أربعــة‬\n      ‫دكاكــن يف عمارتــي  الواقعــة يف شــارع ‪ ...‬ج ‪ ...‬رقــم القطعــة …‬\n      ‫واململوكــة لــي مبوجــب الصــك رقــم ‪ 3/3/976‬يف ‪1413/11/6‬ه ـ‬\n      ‫الصــادر مــن كتابــة عــدل ينبــع إيجــار ســنوي وقــدرة ســتون ألــف ريــال‬\n      ‫للســنة الواحــدة ومــدة اإلجــارة ثــاث ســنوات بدايــة مــن ‪1432/1/1‬ه ـ‬\n      ‫حتــى ‪1434/12/30‬ه ـ واإليجــار يدفــع يف بداية كل ســنة وقد اســتلمت‬\n      ‫تســعني ألــف ريــال وبقــي تســعون ألــف ريــال حالــة حســب الشــرط بــان‬\n      ‫تدفــع كل ســنة يف بدايتهــا وإننــي اطلــب احلكــم علــى املدعــى عليــه‬\n      ‫بــان يدفــع لــي التســعني األلــف وأســأل موكلــة اجلــواب وبعــرض الدعــوى‬\n      ‫ا إن موكلــي‬        ‫املرصــودة بعاليــة علــى املدعــى عليــه وكالــة أجــاب قائ ـ ً‬\n      ‫يريــد أن يفتــح يف تلــك احملــات صيدليــة حســب االتفــاق مــع املؤجــر‬\n      ‫وتقدمنــا بطلــب إلــى البلديــة والشــؤون الصحيــة وقالــوا بــان احملــل‬\n      ‫غيــر مطابــق لشــروط فتــح الصيدليــة لعــدم وجــود مواقــف لهــا حســب‬\n      ‫الكوشــان وكتبنــا خطــاب للمؤجــر بعــدم رغبتنــا يف الدكاكــن‬\n      ‫وطالبنــاه بإعــادة املبلــغ املدفــوع لــه وبعــرض ذلــك علــى املدعــي قــال‬\n      ‫بــان املســتأجر لــم يشــترط بــأن يؤجرهــا صيدليــه ولــم يشــترط خــروج‬\n\n\n‫‪325‬‬\n\f‫تصريــح مــن البلديــة او مــن الشــؤون الصحيــة بــل إنــه قــال لــي بانــه يريــد‬\n‫ان يفتــح لهــا مكتبــا للمصاعــد ومســتودع وانشــطه أخــرى أمــا الشــرط‬\n‫بــان أخــرج عليهــا تصريحــا فلــم يحصــل ذلــك الشــرط بيننــا ثــم طلبــت‬\n‫مــن املدعــي صــورة مــن صــك العمــارة وقــال أطلــب جلســة وحــدد لهــم‬\n‫جلســة وذلــك يف يــوم االثنــن ‪1434/4/29‬ه ـ الســاعة الثامنــة والنصــف‬\n‫صباحــا  ففــي يــوم  االثنــن املوافــق‪ 1434/04/29‬ه ـ افتتحــت اجللســة‬\n‫الســاعة   وفيهــا حضــر املدعــي أصالــة وحضــر كذلــك املدعــى عليــه‬\n‫وكالــة ‪ ................‬ثــم أحضــر املدعــي صــورة لصــك عقــاره برقــم‬\n‫‪ 3/3/976‬يف ‪1413/11/6‬ه ـ الصــادر مــن كتابــة عــدل ينبــع واآليــل‬\n‫إليــه بالشــراء وهــو علــى القطعــة رقــم ‪ 546‬واحملــدودة شــماال قطعــة‬\n‫األرض ‪ 547‬بطــول ‪ 17‬مــت و‪40‬ســم ويحدهــا جنوبــا قطعــة االرض رقــم‬\n‫‪ 545‬وبطــول ‪17‬م و ‪20‬ســم ويحدهــا شــرقا قطعــة قــم ‪ 541‬وبطــول ‪17‬‬\n‫م و‪6‬ســم ويحدهــا غربــا شــارع عــرض ‪ 30‬متــر ًا وبطــول ســتة عشــر متــرا‬\n‫ونــص ومســاحتها ‪294‬متــر و‪ 54‬ســم ثــم طلبــت مــن املدعــي إبــراز عقــد‬\n‫االيجــار فأبــرز لنــا عقــد االيجــار الصــادر مــن مكتــب ‪ ............‬العقــاري‬\n‫والــذي جــاء يف قولــة الطــرف األول ‪ .....................‬نــوع امللــك احملــات‬\n‫الواقعــة بالعمــارة الواقعــة علــى طريــق … الطــرف الثانــي املســتأجر‬\n‫شــركة ‪ ...................‬وميثلهــا ‪ ................‬لقــد مت االتفــاق بــن الطرفــن‬\n‫املذكوريــن بغاليــة علــى تأجيــر الطــرف االول علــى الطــرف الثانــي‬\n‫احملــات بالشــروط التاليــة قيمــة االيجــار ســتون الــف ريــال  ســنوي مــدة‬\n‫االيجــار اعتبــارا مــن ‪1432/1/1‬ه ـ إلــى ‪1434/12/30‬ه ـ ثالث ســنوات‬\n‫فقــط ويدفــع الطــرف الثانــي االيجــار مقدمــا يف أول العقــد ويف حالــة‬\n‫تأخــره عــن الدفــع يحــق للطــرف االول فســخ العقــد دون احلاجــة إلــى‬\n\n\n                                                                                         ‫‪326‬‬\n\f      ‫انــذار او تنبيــه مــع حتميلــة جميــع االضــرار الناجتــة عــن ذلــك كمــا ان‬\n      ‫أي مبلــغ مدفــوع مــن االيجــار ال يعتبــر واردا لــدى الطــرف االول مالــم‬\n      ‫يكــن مدفوعــا مبوجــب شــيك علــى احــد البنــوك او مبوجــب ســند موقــع‬\n      ‫ومختــوم مــن املؤجــر يف حالــة عــدم رغبــة احــد الطرفــن يف جتديــد‬\n      ‫العقــد فعليــه إشــعار الطــرف االخــر يف عــدم رغبتــه يف جتديــد العقــد‬\n      ‫مبــدة ال تقــل عــن ‪ 15‬يومــا قبــل انتهــاء العقــد وإال كان العقــد ســاري‬\n      ‫املفعــول وبنفــس الشــروط وهنــاك عــدة شــروط مــن احملافظــة علــى‬\n      ‫العــن وعــدم تأجيرهــا علــى الغيــر ويحــق للمؤجــر الطــرف االول إنهــاء‬\n      ‫هــذا العقــد إذا اخــل املســتأجر الطــرف الثانــي بــأي شــرط مــن الشــروط‬\n      ‫املذكــورة حــرر يف ‪1432/11/1‬ه ـ ودفعــت ســتون الــف ريــال مبوجــب‬\n      ‫شــيك علــى ‪ ...‬ايجــار الفتــرة مــن ‪1432/7/1‬ه ـ إلــى ‪1433/6/30‬ه ـ‬\n      ‫وبعــرض هــذا العقــد علــى املدعــى عليــه وكالــة قــال نعــم هــذا العقــد‬\n      ‫ا دفعنــا لــه ‪ 90‬الــف ريــال علــى دفعتــن ‪ 60‬الــف و ‪ 30‬الــف‬  ‫صحيــح وفعـ ً‬\n      ‫ثــم ســألت املدعــى عليــه وكالــه الديــك بينــه علــى أن موكلــك اشــترط‬\n      ‫بــأن تكــون احملــات نشــاطها صيدليــة والبــد مــن خــروج تصريــح عليهــا‬\n      ‫مــن البلديــة والشــئون الصحيــة أجــاب بأنــه بينتــي مــع املدعــي وبنــاء علــى‬\n      ‫دعــوى املدعــي وجــواب املدعــى عليــه وعقــد االيجــار الــذي قدمــه املدعــي‬\n      ‫ولــم يشــترط فيــه شــيئ ًا بالنســبة للصيدليــة ويف الواقــع ان املدعــى عليــه‬\n      ‫دفــع مــن االيجــار دفعتــن ‪ 60‬الــف و‪ 30‬الــف ريــال وهــذا دليــل علــى رضاه‬\n      ‫بــل ان مــدة العقــد وهــي ثــاث ســنوات قــد اوشــكت علــى االنتهــاء فلــم‬\n      ‫يأتــي بالشــروط التــي ذكرهــا إال بعــد انتهــاء العقــد لــذا حكمــت علــى‬\n      ‫املدعــى عليــه بــأن يدفــع للمدعــي باقــي إيجــاره وهــو تســعون الــف ريــال‬\n      ‫وبعــرض احلكــم علــى املدعــي قنــع امــا املدعــى عليــه فلــم يقنــع وجــرى‬\n\n\n‫‪327‬‬\n\f   ‫تســليمه صــورة الصــك وافهمتــه مــدة االعتــراض ثالثــون يومــا بعدهــا‬\n   ‫اذا لــم يقــدم اعتراضــه يســقط وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/04/29‬ه ـ‬\n   ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده   وبعــد‬\n‫فلــدي أنــا ‪   ................................‬القاضــي يف احملكمــة العامــة بينب ـع   ‬\n   ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة العامــة‬\n   ‫بينبــع املســاعد برقــم ‪ 3474920‬وتاريــخ ‪ 1434/02/16‬هــ  املقيــدة‬\n‫باحملكمــة برقــم ‪ 34377114‬وتاريــخ ‪ 1434/02/16‬هــ  ففــي يــوم  ‬\n   ‫الثالثــاء املوافــق‪ 1434/08/09‬ه ـ افتتحــت اجللســة وفيهــا وردت املعاملــة‬\n   ‫مــن محكمــة االســئناف مبكــة املكرمــة برقــم ‪ 34377114‬يف‬\n   ‫‪1434/7/24‬هـ واملتعلقة بدعوى ‪ ...................‬ضد شــركة ‪..................‬‬\n   ‫والصــادر فيهــا القــرار رقــم ‪ 34272313‬يف ‪1434/07/18‬هـ من الدائرة‬\n   ‫احلقوقيــة السادســة  وفيــه فقــد جــرى منــا نحــن رئيــس أعضــاء الدائــرة‬\n   ‫احلقوقيــة السادســة يف محكمــة االســئناف مبنطقــة مكــة املكرمــة‬\n   ‫االطــاع علــى هــذا احلكــم الصــادر مــن فضيلــة الشــيخ ‪....................‬‬\n   ‫القاضــي باحملكمــة العامــة بينبــع واملســجل بعــدد ‪ 34204225‬وتاريــخ‬\n   ‫‪1434/05/4‬هـ املتضمن دعوى ‪ ............‬ضد ‪ ..................‬احملكوم فيه‬\n   ‫مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n   ‫تقــررت املوافقــة علــى احلكــم قاضــي اســتئناف ‪ ...................‬رئيــس‬\n   ‫اســتئناف ‪ ..................‬رئيــس  وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/08/09‬ه ـ‬\n   ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n   ‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                            ‫‪328‬‬\n\f      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ .................../‬القاضــي باحملكمــة العامــة‬\n      ‫بينبــع‪ ،‬واملســجل بع ــدد ‪ 34204225‬وتاريــخ ‪1434/5/4‬هـ‪،‬املتضمــن‬\n      ‫دعــوى ‪ .....................‬ضــد شــركة ‪،...................‬احملكــوم في ــه مبــا‬\n      ‫دون باطنــه‪ ،‬وبدراس ــة احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة‬\n      ‫تق ــررت املوافق ــة عل ــى احلكــم‪ ،‬واهلل املوفــق‪ .‬وصل ــى اهلل عل ــى نبينــا‬\n                                                  ‫محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":323,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eac60c130bf34337ccdcea8246339bdcb6520aab52ec7b809d915306bdd34615","normalized_text_hash":"6ad5c989942eec5e6d7e2f6fc971b7ad6003f63f06f23f934b7a445608e8e8e1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p323-34204225"},{"id":"487b6759-7ef0-5409-b7ed-f6a0fb9c92f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -املطالبة بباقي أجرة سيارة وتسليم السيارة -اإلقرار باالدعاء مع الدفع ببيع السيارة واجلهل بحالها -حلف اليمن على ما دفع به -انفساخ عقد اإليجار -تلف العن املؤجرة -تن زيل املدعى عليه منزلة املتلف للسيارة ،االكتفاء بإلزامه بدفع قيمة السيارة بعد خصم ما دفعه من إيجار -تقدير قيمة السيارة من قسم اخلبراء وقت بيعها.","document_number":"33466110","case_number":"32194350","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"عقد -إجارة -املطالبة بباقي أجرة سيارة وتسليم السيارة -اإلقرار باالدعاء مع الدفع ببيع السيارة واجلهل بحالها -حلف اليمن على ما دفع به -انفساخ عقد اإليجار -تلف العن املؤجرة -تن زيل املدعى عليه منزلة املتلف للسيارة ،االكتفاء بإلزامه بدفع قيمة السيارة بعد خصم ما دفعه من إيجار -تقدير قيمة السيارة من قسم اخلبراء وقت بيعها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33466110 :‬‬\n                   ‫َر ْق ُم الدعوى‪32194350 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34203031‬تاريخه‪1434/5/1 :‬هـ‬\n\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬املطالبــة بباقــي أجــرة ســيارة وتســليم الســيارة ‪ -‬اإلقــرار‬\n‫باالدعــاء مــع الدفــع ببيــع الســيارة واجلهــل بحالهــا ‪ -‬حلــف اليمــن‬\n‫علــى مــا دفــع بــه ‪ -‬انفســاخ عقــد اإليجــار ‪ -‬تلــف العــن املؤجــرة ‪ -‬تن ــزيل‬\n‫املدعــى عليــه منزلــة املتلــف للســيارة ‪ ،‬االكتفــاء بإلزامــه بدفــع قيمــة‬\n‫الســيارة بعــد خصــم مــا دفعــه مــن إيجــار ‪ -‬تقديــر قيمــة الســيارة مــن‬\n                                                   ‫قســم اخلبــراء وقــت بيعهــا‪.‬‬\n\n\n\n\n                                ‫‪ -1‬القاعدة الفقهية «ال ضرر وال ضرار»‪.‬‬\n               ‫‪ -2‬قول الفقهاء انفساخ عقد اإلجارة تلف العني املؤجرة ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة «الشــركة» بدعــوى ضــد املدعــى عليــه بأنــه اســتأجر‬\n‫منهــا ســيارة ملــدة وأجــرة معلومــة محــددة دفــع منهــا مقدمــا أربعمائــة ريال‬\n‫إال أنــه لــم يعــد الســيارة حتــى اآلن لــذا فقــد طلــب إلزامــه بإعــادة الســيارة‬\n‫ودفــع أجرتهــا بقــدر األجــرة اليوميــة احملــددة حتــى تاريــخ يــوم إقامــة‬\n‫الدعــوى‪ ،‬أقــر املدعــى عليــه بالعقــد إال أنــه دفــع بتعــذر إعــادة تســليم‬\n‫الســيارة لقيامــه ببيــع الســيارة علــى شــخص ال يعرفــه و قــرر امتناعــه عــن‬\n‫دفــع األجــرة لكونهــا تزيــد عــن قيمتهــا بأضعــاف‪ ،‬جــرى ســؤال املدعيــة‬\n                                                                                          ‫‪354‬‬\n\f      ‫هــل قامــت بالتعميــم علــى الســيارة فأجابــت بأنهــا قامــت بإبــاغ الشــرطة‬\n      ‫بعــد شــهر مــن العقــد‪ ،‬جــرى عــرض ميــن املدعــى عليــه علــى مــا دفــع بــه‬\n      ‫مــن قيامــه ببيــع الســيارة وأنهــا ليســت بحوزتــه وال يعلــم مكانهــا فقــرر‬\n      ‫وكيــل الشــركة املدعيــة بأنــه يطلــب ميينــه وحلــف اليمــن املطلوبــة‪،‬‬\n      ‫جــرى الكتابــة ألهــل اخلبــرة لتقديــر قيمــة الســيارة وقــت العقــد فعــادت‬\n      ‫اإلفــادة بذلــك‪ ،‬جــرى ســؤال املدعيــة هــل قامــت بالتأمــن علــى  الســيارة‬\n      ‫ضــد الســرقة فأجابــت بالنفــي‪ ،‬عليــه وألن املدعــي وكالــة قــرر عــدم‬\n      ‫علمــه بالســيارة املســتأجرة اآلن وألن املدعــى عليــه قــرر أنــه قــام ببيــع‬\n      ‫الســيارة يف أول يــوم وأدى اليمــن بعــد طلبهــا منــه علــى بيعــه للســيارة‬\n      ‫يف أول يــوم اســتأجرها فيــه وألن بيــع املدعــى عليــه للســيارة يعــد إتالفــا‬\n      ‫لهــا وخصوصــا مــع طــول املــدة وعــدم معرفتهمــا للشــخص األجنبــي‬\n      ‫الــذي مت بيــع الســيارة لــه وتعــذر العثــور علــى الســيارة وألن املدعــى‬\n      ‫عليــه يتحمــل ويضمــن قيمــة الســيارة وقــت اإلتــاف لتعديــه وتفريطــه‬\n      ‫وال عبــرة مبطالبــة املدعــي وكالــة باألجــرة طيلــة هــذه املــدة باعتبــار‬\n      ‫تلــف العــن املســتأجرة بتفريــط املدعــى عليــه وملــا نــص عليــه الفقهــاء‬\n      ‫مــن انفســاخ عقــد األجــرة بتلــف املعقــود عليــه وملــا جــاء يف قــرار هيئــة‬\n      ‫النظــر املتضمــن تقديــر قيمــة الســيارة وقــت بيعهــا بعشــرين ألــف ريــال‬\n      ‫وألن املدعــي وكالــة قــرر أن املدعــى عليــه ســدد أجــرة قدرهــا أربعمائــة‬\n      ‫ريــال وألن املدعــى عليــه أدى اليمــن يف أمــر ال يعلــم إال مــن قبلــه علــى أنــه‬\n      ‫بــاع الســيارة يف أول يــوم فقــط وللقاعــدة الفقهيــة «ال ضــرر وال ضــرار»‬\n      ‫وجلميــع مــا تقــدم فقــد ألزمــت الدائــرة املدعــى عليــه بــأن يدفــع للمؤسســة‬\n      ‫املدعيــة تســعة عشــر ألفــا وســتمائة ريــاال وإخــاء ســبيل املدعــى عليــه‬\n      ‫فيمــا ســوى ذلــك‪ ،‬قــرر املدعــى عليــه القناعــة بينمــا اعتــرض وكيــل‬\n\n\n‫‪355‬‬\n\f‫املدعيــة فأفهــم بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n  ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ......................‬القاضــي يف احملكمــة‬\n  ‫العامــة بالريــاض   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n  ‫احملكمــة العامــة بالرياض‪/‬املســاعد برقــم ‪ 32194350‬وتاريــخ‬\n  ‫‪ 1432/05/26‬هــ   املقيــدة باحملكمــة برقــم ‪ 32587005‬وتاريــخ‬\n  ‫‪ 1432/05/21‬هــ  ففــي يــوم  اإلثنــن املوافــق‪ 1433/07/28‬ه ـ افتتحــت‬\n‫اجللســة األولى الســاعة ‪  02 : 15‬وفيها حضر  ‪   .......................‬ســعودي  ‬\n  ‫اجلنســية مبوجــب الســجل املدنــي رقــم    ………………‪ ..‬بصفتــه‬\n  ‫وكيــا عــن ‪ ..................‬بصفتــه صاحــب معــرض ‪ .............‬للســيارات‬\n  ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض‬\n  ‫رقــم ‪ 100570‬يف ‪1428/ 11/16‬ه ـ واملخــول لــه فيهــا حــق املرافعــة‬\n  ‫واملدافعــة واالقــرار والصلــح و أدعــى علــى احلاضــر معــه ‪.......................‬‬\n  ‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ ................‬قائــا يف حتريــر دعــواه‬\n‫لقــد اســتأجر املدعــى عليــه مــن موكلتــي ســيارة ‪ ....‬انتــاج عــام ‪ ...‬م‬\n‫بتاريــخ ‪1427/05/02‬ه ـ بأجــرة يوميــة قدرهــا خمســون ريــاال ســدد منها‬\n‫أربعمائــة ريــال فقــط وحتــى تاريخــه لــم نعثــر عليــه ولــم جنــد الســيارة‬\n‫املذكــورة نطلــب إلزامــه بدفــع أجــرة الســيارة حتــى تاريــخ هــذا اليــوم‬\n‫وقدرهــا مائــة و اثنــا عشــر الفــا ومائتــان وخمســون ريــاال وكذلــك إعــادة‬\n‫الســيارة هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا مــا‬\n‫ذكــره املدعــى يف دعــواه كلــه صحيــح وأنــا بعــد مــا اســتلمت الســيارة‬\n‫قمــت ببيعهــا علــى شــخص ال أعرفــه ســوداني اجلنســية مببلــغ وقــدره‬\n\n                                                                                          ‫‪356‬‬\n\f        ‫خمســة آالف ريــال فقــط وســبب ذلــك حاجتــي للمــال وســوء حالتــى‬\n        ‫النفســية ممــا أدى لتصــريف تصرفــات غيــر مقبولــة وأنــا مقــر بخطــأي‬\n        ‫وأنــا ال أســتطيع ســداد مبلــغ األجــرة ألنــه ليــس معقــول عقــا حيــث إن‬\n        ‫املبلــغ املطالــب بــه يفــوق قيمــة الســيارة أضعافــا مضاعفــة و أنــا مســتعد‬\n        ‫بســداد قيمــة مبلــغ الســيارة كامــا و أمــا الســيارة فــا ميكــن إرجاعهــا‬\n        ‫ألننــي ال أعلــم أيــن هــي هكــذا أجــاب وبعرض ذلك علــى املدعي وكالة‬\n        ‫قــال أنــا أطالــب بأجــرة الســيارة حتــى تاريخــه والســيارة ال نعــرف مقرهــا‬\n        ‫ومــا ذكــره مــن بيعهــا ال نعلــم صحتــه هكــذا ذكــر وبعــد ذلــك جــرى‬\n      ‫ســؤال املدعــي وكالــة عــن قيمــة الســيارة وقــت التأجيــر فأجــاب قائــا ‬\n        ‫موكلتــى اشــترت الســيارة مــن املعــرض جديــدة وال أعلــم مبلــغ الشــراء‬\n        ‫هكــذا ذكــر  بعــد ذلــك أفهمــت املدعــي وكالــة بإحضــار اســتمارة‬\n        ‫الســيارة وبيــان قيمــة الســيارة وقــت الشــراء فاســتعد بذلــك والنتهــاء‬\n        ‫وقــت اجللســة جــرى رفعهــا ‪ ،‬يف يــوم  األربعــاء املوافــق‪ 1433/08/21‬ه ـ‬\n        ‫افتتحــت اجللســة الثانيــة الســاعة ‪ 00:08‬وفيهــا حضــر املدعــي وكالــة‬\n        ‫واملدعــى عليــه وأبــرز املدعــي وكالــة وثيقــة ملكيــة ســيارة نــوع ‪....‬‬\n        ‫صنــع … واملالــك …‪ .‬ورقــم هويــة املالــك ‪ ....‬رقــم اللوحــة ‪ ...‬وبســؤال‬\n        ‫املدعــي وكالــة عــن مبلــغ الشــراء وهــل مت البــاغ عــن الســيارة  فأجــاب‬\n      ‫قائــا الشــراء كان مببلــغ وقــدره أربعــة وعشــرون ألفــا وســبعمائة ريــال  ‬\n        ‫وموكلتــي تطالــب بقيمــة الســيارة احلاليــة مــع األجــرة إضافــة إلــى ‪2000‬‬\n        ‫تأمــن علــى الســيارة وبذلــك تصبــح جميــع املبالــغ املطالــب بهــا قدرهــا‬\n        ‫مائــة وســبعة وعشــرون ألفــا وثمامنائــة وخمســون ريــاال  وموكلتــي أبلغــت‬\n        ‫عــن الســيارة بعــد شــهر تقريبــا مــن تاريــخ العقــد هكــذا ذكــر بعــد ذلــك‬\n        ‫ومبــا ان املــدة طويلــة واملدعــى عليــه قــرر بيعــه للســيارة لشــخص اليعرفــه‬\n\n\n‫‪357‬‬\n\f‫وعــدم علــم املدعــي مبوقــع الســيارة أو وجودهــا أفهمــت املدعــي وكالــة‬\n‫بــأن لــه ميــن املدعــى عليــه علــى بيعــه للســيارة وعــدم معرفتــه ملكانهــا‬\n‫اآلن بالصيغــة التاليــة ( واهلل بأننــي قمــت ببيــع الســيارة علــى شــخص‬\n‫ســوداني يف نفــس يــوم اســتالمي للســيارة مببلــغ وقــدره خمســة آالف‬\n‫ريــال وال أعلــم مكانهــا اآلن) فقــال أنــا أطلــب ميينــه ووكالتــه مخــول‬\n‫لــه فيهــا حــق طلــب اليمــن وبعــرض اليمــن علــى املدعــى عليــه اســتعد‬\n‫بأدائهــا فأذنــت لــه فحلــف قائــا واهلل بأننــي قمــت ببيــع الســيارة علــى‬\n‫شــخص ســوداني يف نفــس يــوم اســتالمي للســيارة مببلــغ وقــدره خمســة‬\n‫آالف ريــال وال أعلــم مكانهــا اآلن هكــذا حلــف بعــد ذلــك اقتضــى‬\n‫النظــر الكتابــة لهيئــة النظــر باحملكمــة العامــة لتقديــر قيمــة الســيارة‬\n‫املســتأجرة وقــت اســتئجار املدعــى عليــه للســيارة يف ‪1427/5/2‬ه ـ‬\n                                   ‫وحتــى ورود اإلجابــة جــرى رفــع اجللســة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ......................‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالرياض‪/‬املســاعد برقــم ‪ 32194350‬وتاريــخ‬\n‫‪ 1432/05/26‬هــ   املقيــدة باحملكمــة برقــم ‪ 32587005‬وتاريــخ‬\n‫‪ 1432/05/21‬هــ  ففــي يــوم  الســبت املوافــق‪ 1433/11/27‬ه ـ افتتحت‬\n‫اجللســة الثالثــة  الســاعة ‪  08.00‬وفيهــا حضــر املدعــي وكالــة احلاضــر‬\n‫ســابقا واملدعــى عليــه وقــد وردنــا قــرار هيئــة النظــر رقــم ‪ 1/1388‬يف‬\n‫‪1433/9/10‬ه ـ املتضمــن أنــه متــت الكتابــة لشــيخ املعــارض ومت تقديــر‬\n‫الســيارة مببلغ قدره عشــرون ألف ريال وذلك بتاريخ ‪1427/5/2‬هـ  أ هـ‬\n‫وبعــرض ذلــك علــى الطرفــن قــاال هــذا قــرار مــن أهــل اخلبــرة والنعتــرض‬\n‫عليــه بعــد ذلــك جــرى ســؤال املدعــي وكالــة عــن مبلــغ التامــن واألوراق‬\n\n\n                                                                                        ‫‪358‬‬\n\f      ‫التــي تثبتــه فقــال ليــس لــدي أوراق وأنــا متنــازل عــن مبلــغ التامــن لقلتــه  ‬\n        ‫فبنــاء علــى ماتقــدم ومبــا أن املدعــي وكالــة قــرر عــدم علمــه بالســيارة‬\n        ‫املســتأجرة واآلن ومبــا أن املدعــى عليــه قــرر أنــه قــام ببيــع الســيارة يف‬\n        ‫أول يــوم  وأدى اليمــن بعــد طلبهــا منــه علــى بيعــه للســيارة يف أول يــوم‬\n        ‫اســتأجرها فيــه  ومبــا أن بيــع املدعــى عليــه للســيارة يعــد إتالفــا لهــا‬\n        ‫وخصوصــا مــع طــول املــدة وعــدم معرفتهمــا للشــخص األجنبــي الــذي‬\n        ‫مت بيــع الســيارة لــه وتعــذر العثــور علــى الســيارة ومبــا أن املدعــى عليــه‬\n        ‫يتحمــل ويضمــن قيمــة الســيارة وقــت االتــاف لتعديــه وتفريطــه وال عبرة‬\n        ‫مبطالبــة املدعــي وكالــة باألجــرة طيلــة هــذه املــدة باعتبــار تلــف العــن‬\n        ‫املســتأجرة بتفريــط املدعــى عليــه وملــا جــاء يف قرار هيئــة النظر املتضمن‬\n        ‫تقديــر قيمــة الســيارة وقــت بيعهــا  مببلــغ قــدره عشــرون ألــف ريــال ومبــا‬\n        ‫أن املدعــي وكالــة قــرر أن املدعــى عليــه ســدد أجــرة قدرهــا أربعمائــة‬\n        ‫ريــال ومبــا أن املدعــى عليــه أدى اليمــن يف أمــر ال يعلــم إال مــن قبلــه علــى‬\n        ‫أنــه بــاع الســيارة يف أول يــوم ممــا يســتحق معــه املؤسســة  املدعيــة أجــرة‬\n        ‫اليــوم األول فقــط  جلميــع ماتقــدم فقــد ألزمــت املدعــى عليــه بــأن يدفــع‬\n        ‫للمؤسســة املدعيــة مبلغــا وقــدره تســعة عشــر ألفــا وســتمائة وخمســون‬\n        ‫ريــاال وأخليــت ســبيل املدعــى عليــه فيمــا ســوى ذلــك وبذلــك حكمــت‬\n        ‫وبعــرض احلكــم علــى الطرفــن قنــع املدعــي عليــه وقــرر املدعــي وكالــة‬\n        ‫عــدم قناعتــه باحلكــم وطالــب بتدقيــق احلكــم واســتعد بتقــدمي الئحــة‬\n        ‫اعتراضيــة وأفهــم بأنــه لــه مــدة قدرهــا ثالثــون يــوم لتقــدمي اعتراضــه‬\n        ‫اعتبــارا مــن تاريــخ اســتالم صــورة مــن نســخة احلكــم وإذا مضــت املــدة‬\n        ‫احملــددة لالعتــراض ولــم يقــدم الئحتــه فيهــا ســقط حقــه يف االســتئناف‬\n        ‫واكتســب احلكــم القطعيــة وحــدد موعــد تســليم صــورة نســخة احلكــم‬\n\n\n‫‪359‬‬\n\f  ‫هــذا اليــوم الســاعة الواحــدة ظهــرا ومت إقفــال اجللســة الســاعة ‪08.30‬‬\n  ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف  ‪1433/11/27‬ه ـ‬\n  ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ......................‬القاضــي يف احملكمــة‬\n  ‫العامــة بالريــاض   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n  ‫احملكمــة العامــة بالرياض‪/‬املســاعد برقــم ‪ 32194350‬وتاريــخ‬\n  ‫‪1432/05/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32587005‬وتاريــخ‬\n  ‫‪1432/05/21‬هــ  ففــي يــوم  األربعــاء املوافــق ‪ 1434/03/04‬هــ  حيــث‬\n  ‫عــادت املعاملــة مــن محكمــة االســتئناف مبوجــب خطــاب رئيــس‬\n  ‫محكمــة االســتئناف رقــم ‪ 332172165‬يف ‪1434/1/17‬ه ـ وبرفقهــا‬\n‫قــرار املالحظــة الصــادر مــن الدائــرة الثانيــة لتمييــز القضايــا احلقوقيــة  ‬\n  ‫برقــم ‪ 341493‬يف ‪1434/1/4‬هــ  ونــص احلاجــة منــه (لوحــظ أن املدعــي‬\n  ‫أبلــغ اجلهــات األمنيــة عــن الســيارة املذكــورة ولــم يتأكــد فضيلتــه‬\n  ‫عــن هــذا التعميــم مــن العثــور علــى الســيارة مــن عدمــه والبــد مــن ذلــك‬\n  ‫كمــا أن احلكــم بقيمــة الســيارة فقــط مــع أنــه اســتعملها بعقــد اجــارة‬\n  ‫فيــه نظــر فعلــى فضيلتــه مالحظــة ذلــك حيــث إن عقــد اإلجــارة الزم‬\n  ‫وال يفســخ إال مبســوغ شــرعي ) وعليــه ســيتم الكتابــة ملديــر شــرطة‬\n  ‫منطقــة الريــاض لإلفــادة عــن الســيارة مــدار الدعــوى وهــل مت العثــور‬\n  ‫عليهــا أم ال  علمــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/03/04‬ه ـ ويف يــوم  اإلثنــن‬\n  ‫املوافــق‪ 1434/04/15‬ه ـ حيــث وردنــا خطــاب مدير شــرطة النســيم رقم‬\n  ‫‪ 6/9604/2‬يف ‪1434/4/2‬ه ـ املتضمــن أنــه مت التعميــم علــى الســيارة‬\n  ‫بتاريــخ ‪1427/5/14‬ه ـ ولــم يتــم العثــور عليهــا حتــى تاريخــه أ‪.‬ه ـ وأمــا‬\n\n\n                                                                                          ‫‪360‬‬\n\f         ‫مــا يتعلــق بعقــد األجــرة ولزومــه فأجيــب عــن ذلــك بــأن هــذا متفــق عليــه‬\n         ‫مــع وجــود العــن املؤجــرة واســتفادة املدعــى عليــه منهــا وأمــا مــع عــدم‬\n         ‫وجودهــا فالعــن يف حكــم املعدومــة ومت تضمــن املدعــى عليــه قيمتهــا‬\n         ‫وقــت إتالفهــا لتعديــه بذلــك والقاعــدة الشــرعية تنــص علــى أنــه (ال ضرر‬\n         ‫وال ضــرار) وهــي مبنيــة علــى قولــه صلــى اهلل عليــه وســلم (ال ضــرر وال‬\n         ‫ضــرار) وقــد أزيــل الضــرر عــن املدعــي بتعويضــه عــن قيمــة الســيارة مــن‬\n         ‫تاريــخ اليــوم الــذي فقــدت فيــه الســيارة وحلــف بــه املدعــى عليــه لعــدم‬\n         ‫العلــم بتاريــخ فقــد الســيارة إال مــن قبلــه وبذلــك ال ضــرر علــى الشــركة‬\n         ‫املدعيــة ألنــه مت تعويضهــا بكامــل قيمــة الســيارة وقــت التلــف ال وقــت‬\n         ‫احلكــم كمــا أن التأخيــر يف مطالبــة الشــركة املدعيــة طيلــة هــذه‬\n         ‫املــدة بحســب تاريــخ قيــد املعاملــة باحملكمــة بتاريــخ ‪1432/5/21‬ه ـ‬\n         ‫يعــد تفريــط منهــا يف املطالبــة والعبــرة بتلــف العــن املؤجــرة يف األجــرة‬\n         ‫ال تاريــخ املطالبــة وقــد نــص الفقهــاء علــى انفســاخ عقــد اإلجــارة بتلــف‬\n         ‫العــن املؤجــرة وبذلــك لــم يظهــر لــي ســوى ماحكمــت بــه  وبــاهلل‬\n         ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                        ‫يف  ‪1434/04/15‬ه ـ‬\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪ .........‬املالزم القضائي لدى فضيلة …‪   ..‬‬\n         ‫القاضــي يف احملكمــة العامــة بالريــاض   وبنــاء علــى املعاملــة احملالــة لنــا‬\n         ‫من فضيلة رئيس احملكمة العامة بالرياض املساعد برقم ‪32194350‬‬\n         ‫وتاريــخ ‪1432/05/26‬هــ  املقيــدة باحملكمــة برقــم ‪ 32587005‬وتاريــخ‬\n         ‫‪1432/05/21‬ه ـ ففــي يــوم  األربعــاء املوافق‪1434/05/22‬ه ـ حيــث‬\n         ‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار املــدون علــى‬\n      ‫ظهــر الصــك  واملتضمــن مــا نصــه (تظهيــرات الدائــرة احلقوقيــة  الثانيــة  ‬\n\n\n‫‪361‬‬\n\f                                                      ‫مبحكمــة االســتئناف بالريــاض‬\n  ‫احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33466110‬‬\n  ‫وتاريــخ ‪1433/11/27‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n‫العامــة بالريــاض الشــيخ … وأصدرنــا القــرار رقــم ‪ 34203031‬وتاريــخ  ‬\n  ‫‪1434/5/1‬هــ  املتضمــن أنــه لــم يظهــر مــا يوجب املالحضــة بعد اإلجراء‬\n  ‫األخيــر   واهلل املوفــق قاضــي اســتئناف ‪   ................‬ختمــه وتوقيعــه‬\n  ‫قاضــي اســتئناف ‪   ........................‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n  ‫‪  ...........................‬ختمــه وتوقيعــه ) وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/05/22‬ه ـ‬\n  ‫احلمــدهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n  ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n  ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n  ‫‪  34154430‬وتاريخ‪1433/11/30‬هــ  املرفــق بهــا الصــك الصــادر مــن‬\n  ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .................................‬املســجل برقم‬\n  ‫‪ 33466110‬وتاريــخ ‪1434/4/17‬ه اخلــاص بدعــوى ‪ ................‬وكالــة‬\n  ‫ضــد ‪ ..............‬وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة‬\n  ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n  ‫ـاء علــى قرارنــا رقــم ‪ 341493‬يف ‪1434/01/04‬هــ  لــم يظهــر‬               ‫بالصــك بنـ ً‬\n‫مــا يوجــب املالحظــة بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى  ‬\n                                                              ‫نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n                                                                                               ‫‪362‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":354,"source_page_end":362,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b04e7063c4a54f266c7dc5a90eb5a7f591676ff3cc2345db7699a36ac010cac8","normalized_text_hash":"c8f5c07326ac103cc1ba15ca3073abfef13839209e07449928c24fe3ebf00ab0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p354-33466110"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

